window.STB_PFAD = {
  ROADMAP: [
    { id: 'grund', n: 'Grundlagen und Methode', em: '🧭', goal: 'Fallbearbeitung und Gutachtenaufbau, Steuerbegriff und Steuerarten, Eingriffsrecht und Auslegung, Rechtsquellen und Rückwirkung, Finanzverfassung und Grundrechte (Studienbrief 1 und Anfang 2).' },
    { id: 'ao', n: 'Abgabenordnung', em: '📜', goal: 'Steuerschuldverhältnis, Haftung, Steuerverwaltungsakt und Bekanntgabe, Festsetzungsverfahren, Verjährung, Grundlagen- und Folgebescheid, Änderung, Einspruch und Klage (Studienbrief 2).' },
    { id: 'est', n: 'Einkommensteuer', em: '🧾', goal: 'Steuerpflicht, das Schema des § 2 EStG, Überschuss- und Gewinneinkünfte, Arbeitnehmer, Gewerbe, Kapital, Vermietung, private Veräußerungen, Sonderausgaben und außergewöhnliche Belastungen (Studienbrief 3).' },
    { id: 'unt', n: 'Unternehmenssteuerrecht', em: '🏢', goal: 'Einzelunternehmer und Mitunternehmerschaft, vermögensverwaltende Personengesellschaften, Betriebsveräußerung, Körperschaftsteuer, Trennungsprinzip, vGA, Organschaft und Gewerbesteuer (Studienbrief 4).' },
  ],
  RANKS: [[0, 'Erstsemester'], [10, 'Normleserin mit Plan'], [30, 'Gutachtenschreiber'], [60, 'Klausurprofi'], [100, 'Finanzrichter in spe']],
  LESSONS: {
    grund: [
      { id: 'g1', t: 'Fallbearbeitung: vier Klausurkonstellationen', norms: ['Gutachtenstil', 'Ermächtigung', 'formell', 'materiell'],
        why: 'Die Fallfrage entscheidet über den Aufbau. Wer erkennt, ob nach Klage, Einspruch, Rechtmäßigkeit oder nur nach den Einkünften gefragt ist, hat die halbe Gliederung schon geschrieben.',
        core: ['Es gibt vier typische Fallfragen. Erstens prozessual: Hat die Klage Erfolg? Dann Zulässigkeit (Finanzrechtsweg, statthafte Klageart, Klagebefugnis, erfolgloses Vorverfahren, Klagefrist) und Begründetheit. Zweitens behördlich: Hat der Einspruch Erfolg? Dann Zulässigkeit (Statthaftigkeit, Beschwer, Frist, Form) und Begründetheit. Drittens: Ist der Bescheid (Steuer-, Haftungs- oder Änderungsbescheid) rechtmäßig? Viertens rein materiell: Welche Einkünfte, welche Summe der Einkünfte, welches zu versteuernde Einkommen? Die ersten drei sind Einkleidungen; in der Begründetheit landen sie bei der Rechtmäßigkeit des Bescheids, und dort wiederum bei der materiellen Prüfung. Das Steuerrecht ist ein Baukasten aus diesen Schubladen.',
          'Die Rechtmäßigkeit prüft man dreistufig: 1. Ermächtigungsgrundlage (Steuerrecht ist Eingriffsrecht, also braucht jeder belastende Bescheid eine gesetzliche Grundlage, etwa § 155 AO für den Steuerbescheid, § 191 AO für den Haftungsbescheid, § 173 AO für eine Änderung). 2. Formelle Rechtmäßigkeit: Zuständigkeit (Finanzamt, Gemeinde, Familienkasse), Verfahren (Anhörung), Form. 3. Materielle Rechtmäßigkeit: keine Festsetzungsverjährung, dann die Steuer- oder Haftungsschuld, also der eigentliche Einkommensteuerfall. Im Gutachtenstil steht vorne die Hypothese („Der Bescheid ist rechtmäßig, wenn …“), dann Definition, Subsumtion, Ergebnis. Unproblematisches knapp, Probleme ausführlich.'],
        schema: ['Fallfrage lesen: Klage, Einspruch, Rechtmäßigkeit oder Einkünfte?', 'Bei Klage/Einspruch: A. Zulässigkeit, B. Begründetheit', 'Begründetheit = Rechtmäßigkeit: Ermächtigung, formell, materiell', 'Materiell: Verjährung, dann Einkunftsart, Höhe, Summe, GdE, Einkommen, zvE', 'Gutachtenstil: Obersatz, Definition, Subsumtion, Ergebnis'],
        case: { sv: 'B erhält einen Einkommensteuerbescheid, in dem ein Verkaufserlös als gewerbliche Einkünfte erfasst ist. Sie legt Einspruch ein, der zurückgewiesen wird. Die Fallfrage lautet: „Hat die Klage der B Aussicht auf Erfolg?“',
          steps: [['Welche Konstellation liegt vor?', 'Prozessualer Einstieg: Erfolgsaussicht einer Klage. Aufbau A. Zulässigkeit, B. Begründetheit.'], ['Welche Klageart ist statthaft?', 'Die Anfechtungsklage (§ 40 Abs. 1 FGO), weil B die Aufhebung oder Änderung eines Verwaltungsakts begehrt.'], ['Wo steckt der materielle Kern?', 'In der Begründetheit: Der Bescheid ist rechtswidrig, wenn der Erlös keine gewerblichen Einkünfte sind; dort wird die Einkunftsart geprüft.']],
          res: 'Klage: Zulässigkeit (Anfechtungsklage nach erfolglosem Einspruch) und Begründetheit, darin die Einkünftequalifikation.' },
        nav: [],
        cards: [['Vier Klausurkonstellationen im Steuerrecht?', 'Klage, Einspruch, Rechtmäßigkeit eines Bescheids, rein materielle Prüfung der Einkünfte.'], ['Drei Stufen der Rechtmäßigkeitsprüfung?', 'Ermächtigungsgrundlage, formelle Rechtmäßigkeit (Zuständigkeit, Verfahren, Form), materielle Rechtmäßigkeit.'], ['Was prüft man in der materiellen Rechtmäßigkeit zuerst?', 'Dass keine Festsetzungsverjährung eingetreten ist; danach die Steuerschuld.'], ['Fünf Schritte der materiellen Einkünfteprüfung?', 'Einkunftsart, Höhe der Einkünfte, Summe der Einkünfte, Gesamtbetrag der Einkünfte, Einkommen bzw. zvE.']] },

      { id: 'g2', t: 'Steuerbegriff, Abgaben und Steuerarten', norms: ['§ 3 AO', 'Gebühr', 'Beitrag', 'direkt/indirekt'], link: 'g1',
        why: 'Ob etwas eine Steuer ist, entscheidet über Gesetzgebungskompetenz, Verfahren und Rechtsweg. Die fünf Merkmale des § 3 Abs. 1 AO gehören ins Langzeitgedächtnis.',
        core: ['Steuern sind nach § 3 Abs. 1 AO Geldleistungen, die keine Gegenleistung für eine besondere Leistung darstellen, von einem öffentlich-rechtlichen Gemeinwesen zur Erzielung von Einnahmen allen auferlegt werden, bei denen der Tatbestand zutrifft, an den das Gesetz die Leistungspflicht knüpft; die Einnahmeerzielung kann Nebenzweck sein (Lenkungsteuern). Abgrenzung innerhalb der Abgaben: Die Gebühr ist Gegenleistung für eine tatsächlich in Anspruch genommene Leistung der Verwaltung (etwa ein Pass), der Beitrag für die bloße Möglichkeit der Inanspruchnahme (etwa Erschließungsbeitrag). Steuern sind voraussetzungslos geschuldet, das Aufkommen fließt grundsätzlich in den allgemeinen Haushalt (Nonaffektation).',
          'Einteilungen: Direkte Steuern treffen den, der sie zahlt (Einkommensteuer), indirekte sollen überwälzt werden (Umsatz- und Verbrauchsteuern: Steuerschuldner und Steuerträger fallen auseinander). Nach dem Gegenstand: Ertragsteuern (Einkommen-, Körperschaft-, Gewerbesteuer), Verkehrsteuern (Umsatz-, Grunderwerbsteuer), Verbrauchsteuern (Energie, Tabak, Alkohol), Aufwandsteuern (Hundesteuer, Zweitwohnungsteuer). Nach § 3 Abs. 3 AO sind auch Einfuhr- und Ausfuhrabgaben Steuern. Steuerliche Nebenleistungen (§ 3 Abs. 4 AO) wie Verspätungszuschläge, Zinsen oder Säumniszuschläge sind keine Steuern, folgen aber deren Verfahrensregeln.'],
        schema: ['Geldleistung', 'Keine Gegenleistung für besondere Leistung', 'Öffentlich-rechtliches Gemeinwesen', 'Einnahmeerzielung (auch als Nebenzweck)', 'Allen auferlegt, bei denen der Tatbestand zutrifft'],
        case: { sv: 'Die Stadt Nordheim verlangt von Hundehaltern 120 € im Jahr. Für die Ausstellung eines Personalausweises verlangt sie 37 €. Grundstückseigentümer an einer neuen Straße zahlen einen Anteil an den Baukosten, auch wenn sie die Straße kaum nutzen.',
          steps: [['Hundesteuer: Steuer im Sinne von § 3 Abs. 1 AO?', 'Ja: Geldleistung ohne Gegenleistung, auferlegt von der Gemeinde; dass sie auch die Hundezahl lenken soll, schadet nicht (Nebenzweck). Es ist eine örtliche Aufwandsteuer.'], ['Ausweisgebühr?', 'Gebühr: Gegenleistung für eine tatsächlich in Anspruch genommene Amtshandlung.'], ['Straßenkostenanteil?', 'Beitrag: Entgelt für die Möglichkeit der Inanspruchnahme, unabhängig von der tatsächlichen Nutzung.']],
          res: 'Hundesteuer = Steuer (Aufwandsteuer), Ausweis = Gebühr, Straßenkosten = Beitrag.' },
        nav: [],
        cards: [['Fünf Merkmale der Steuer nach § 3 Abs. 1 AO?', 'Geldleistung, keine Gegenleistung, öffentlich-rechtliches Gemeinwesen, Einnahmeerzielung (Nebenzweck genügt), Tatbestandsmäßigkeit (allen auferlegt).'], ['Gebühr vs. Beitrag?', 'Gebühr: tatsächliche Inanspruchnahme einer Leistung. Beitrag: Möglichkeit der Inanspruchnahme.'], ['Direkte vs. indirekte Steuer?', 'Direkt: Steuerschuldner trägt sie selbst. Indirekt: Überwälzung auf den Steuerträger gewollt (USt, Verbrauchsteuern).'], ['Sind Verspätungszuschläge Steuern?', 'Nein, steuerliche Nebenleistungen (§ 3 Abs. 4 AO).']] },

      { id: 'g3', t: 'Eingriffsrecht, Auslegung und wirtschaftliche Betrachtung', norms: ['Gesetzesvorbehalt', 'Analogieverbot', '§§ 39–42 AO'], link: 'g2',
        why: 'Zivilrecht und Steuerrecht laufen nicht immer gleich. Die §§ 39 bis 42 AO sind die Scharniere, an denen Klausuren drehen: Wer ist wirtschaftlicher Eigentümer, was gilt bei Scheingeschäften und Missbrauch?',
        core: ['Steuerrecht ist Eingriffsrecht: Nach dem Vorbehalt des Gesetzes darf nur besteuert werden, was ein Gesetz tatbestandlich erfasst. Daraus folgt ein Analogieverbot zulasten des Steuerpflichtigen; Lücken darf die Verwaltung nicht zu seinen Lasten füllen. Ausgelegt wird nach Wortlaut, Systematik, Entstehungsgeschichte und Zweck. Die wirtschaftliche Betrachtungsweise ist keine eigene Methode, sondern teleologische Auslegung: Steuergesetze knüpfen oft an wirtschaftliche Vorgänge an, nicht an die zivilrechtliche Form.',
          'Die AO regelt die Fälle, in denen das Steuerrecht vom Zivilrecht abweicht. § 39 AO: Wirtschaftsgüter werden grundsätzlich dem Eigentümer zugerechnet, aber dem wirtschaftlichen Eigentümer, wenn er den Eigentümer für die gewöhnliche Nutzungsdauer von der Einwirkung ausschließen kann (Treuhand, Sicherungseigentum, Leasing in bestimmten Fällen). § 40 AO: Gesetz- oder sittenwidriges Handeln ist für die Besteuerung unerheblich. § 41 AO: Unwirksame Rechtsgeschäfte werden besteuert, soweit die Beteiligten das wirtschaftliche Ergebnis eintreten lassen; Scheingeschäfte sind unerheblich, besteuert wird das verdeckte Geschäft. § 42 AO: Bei einer unangemessenen Gestaltung, die zu einem gesetzlich nicht vorgesehenen Steuervorteil führt, entsteht der Anspruch so, wie er bei angemessener Gestaltung entstanden wäre, es sei denn, der Steuerpflichtige weist beachtliche außersteuerliche Gründe nach.'],
        schema: ['Ermächtigung im Gesetz? (Gesetzesvorbehalt)', 'Auslegung: Wortlaut, Systematik, Historie, Telos', 'Zurechnung: zivilrechtlicher oder wirtschaftlicher Eigentümer (§ 39)', 'Unwirksam oder sittenwidrig? Trotzdem besteuern (§§ 40, 41)', 'Scheingeschäft: verdecktes Geschäft maßgeblich (§ 41 Abs. 2)', 'Missbrauch: angemessene Gestaltung zugrunde legen (§ 42)'],
        case: { sv: 'H betreibt einen Online-Handel mit Waren, deren Verkauf verboten ist, und erzielt Gewinne. Außerdem schließt er mit seiner Schwester einen Kaufvertrag über ein Grundstück, den beide nicht notariell beurkunden; die Schwester zahlt, zieht ein und nutzt das Grundstück wie eine Eigentümerin.',
          steps: [['Sind die Gewinne aus dem verbotenen Handel steuerbar?', 'Ja, § 40 AO: Ein Gesetzesverstoß ist für die Besteuerung unerheblich.'], ['Wirkt der formunwirksame Kaufvertrag steuerlich?', 'Ja, soweit die Beteiligten das wirtschaftliche Ergebnis eintreten lassen (§ 41 Abs. 1 AO).'], ['Wem ist das Grundstück zuzurechnen?', 'Der Schwester als wirtschaftlicher Eigentümerin (§ 39 Abs. 2 Nr. 1 AO), weil sie Besitz, Nutzen und Lasten hat.']],
          res: '§ 40 AO für den verbotenen Handel, § 41 Abs. 1 und § 39 Abs. 2 AO für den formunwirksamen Kauf.' },
        nav: [],
        cards: [['Warum gilt im Steuerrecht ein Analogieverbot zulasten des Steuerpflichtigen?', 'Steuerrecht ist Eingriffsrecht; der Vorbehalt des Gesetzes verlangt eine gesetzliche Grundlage für jede Belastung.'], ['Wirtschaftliches Eigentum nach § 39 Abs. 2 Nr. 1 AO?', 'Wer den zivilrechtlichen Eigentümer für die gewöhnliche Nutzungsdauer wirtschaftlich von der Einwirkung ausschließen kann.'], ['Was sagt § 41 Abs. 2 AO zu Scheingeschäften?', 'Sie sind unerheblich; ein verdecktes Rechtsgeschäft ist maßgeblich.'], ['Rechtsfolge des § 42 AO?', 'Der Anspruch entsteht so, wie er bei einer angemessenen Gestaltung entstanden wäre, sofern keine beachtlichen außersteuerlichen Gründe nachgewiesen werden.']] },

      { id: 'g4', t: 'Rechtsquellen und Rückwirkung', norms: ['Art. 20 Abs. 3 GG', 'DBA', 'Verwaltungsvorschriften', 'echte/unechte Rückwirkung'], link: 'g3',
        why: 'Welche Norm gilt, und für welchen Zeitraum? Die Unterscheidung echte und unechte Rückwirkung gehört zum Standard, ebenso die Frage, wen BMF-Schreiben eigentlich binden.',
        core: ['Rechtsquellen sind Verfassung, Gesetze, Rechtsverordnungen und kommunale Satzungen (etwa für die Hundesteuer), daneben das Unionsrecht (Vorrang vor nationalem Recht, besonders bei der Umsatzsteuer) und Völkerrecht. Doppelbesteuerungsabkommen werden durch ein Zustimmungsgesetz (Art. 59 Abs. 2 GG) in innerstaatliches Recht umgesetzt und haben den Rang eines einfachen Bundesgesetzes; § 2 AO ordnet ihren Vorrang an, ein späteres Gesetz kann sie aber überschreiben (Treaty Override). Verwaltungsvorschriften (Richtlinien, BMF-Schreiben) binden nur die Verwaltung, nicht den Bürger und nicht die Gerichte. Urteile des BFH binden rechtlich nur im entschiedenen Fall; über die Veröffentlichung im Bundessteuerblatt wendet die Verwaltung sie allgemein an, mit einem Nichtanwendungserlass verweigert sie das.',
          'Zeitlich gilt ein Gesetz ab Inkrafttreten. Rückwirkung ist am Rechtsstaatsprinzip und Vertrauensschutz zu messen. Echte Rückwirkung (Rückbewirkung von Rechtsfolgen) liegt vor, wenn ein Gesetz nachträglich in bereits abgeschlossene Sachverhalte eingreift; sie ist grundsätzlich unzulässig, ausnahmsweise erlaubt, wenn kein schutzwürdiges Vertrauen besteht (etwa unklare Rechtslage). Unechte Rückwirkung (tatbestandliche Rückanknüpfung) liegt vor, wenn ein Gesetz auf gegenwärtige, noch nicht abgeschlossene Sachverhalte einwirkt; sie ist grundsätzlich zulässig, Vertrauensschutz wird abgewogen. Weil die Einkommensteuer erst mit Ablauf des Veranlagungszeitraums entsteht (§ 36 Abs. 1 EStG), ist eine Änderung im laufenden Jahr für dieses Jahr nach der Rechtsprechung regelmäßig nur unechte Rückwirkung.'],
        schema: ['Normenhierarchie: GG, Unionsrecht, Gesetz, Verordnung, Satzung', 'DBA: Zustimmungsgesetz, Rang einfaches Bundesgesetz, § 2 AO', 'Verwaltungsvorschriften: nur verwaltungsintern verbindlich', 'Rückwirkung: Ist der Sachverhalt (die Steuerentstehung) abgeschlossen?', 'Echt: grds. unzulässig; unecht: grds. zulässig, Abwägung'],
        case: { sv: 'Am 1. Oktober eines Jahres wird ein Gesetz verkündet, das eine Steuerbefreiung für das gesamte laufende Jahr streicht. Ein zweites Gesetz streicht die Befreiung zusätzlich für das Vorjahr, für das die Steuer längst festgesetzt ist.',
          steps: [['Laufendes Jahr: echte oder unechte Rückwirkung?', 'Unecht: Die Einkommensteuer entsteht erst mit Ablauf des Jahres; der Sachverhalt ist noch nicht abgeschlossen. Grundsätzlich zulässig, Vertrauensschutz abwägen.'], ['Vorjahr?', 'Echte Rückwirkung: Die Steuer ist bereits entstanden. Grundsätzlich unzulässig.'], ['Binden BMF-Schreiben zur Auslegung das Finanzgericht?', 'Nein, nur die Verwaltung.']],
          res: 'Laufendes Jahr unechte (grds. zulässig), Vorjahr echte Rückwirkung (grds. unzulässig).' },
        nav: [],
        cards: [['Rang eines DBA im deutschen Recht?', 'Einfaches Bundesgesetz (über Zustimmungsgesetz nach Art. 59 Abs. 2 GG); Vorrang nach § 2 AO, aber Treaty Override möglich.'], ['Wen binden BMF-Schreiben?', 'Nur die Finanzverwaltung, nicht Bürger und Gerichte.'], ['Echte Rückwirkung?', 'Eingriff in bereits abgeschlossene Sachverhalte (Rechtsfolgen werden für die Vergangenheit geändert); grundsätzlich unzulässig.'], ['Warum ist eine Änderung des EStG im laufenden Jahr meist nur unechte Rückwirkung?', 'Die ESt entsteht erst mit Ablauf des Veranlagungszeitraums (§ 36 Abs. 1 EStG).']] },

      { id: 'g5', t: 'Finanzverfassung und Grundrechte', norms: ['Art. 105–108 GG', 'Art. 3 GG', 'Leistungsfähigkeit', 'Lenkungsteuer'], link: 'g4',
        why: 'Wer darf eine Steuer erfinden, wer bekommt das Geld, wer verwaltet sie? Und woran misst das Verfassungsgericht Steuergesetze? Das ist der verfassungsrechtliche Rahmen jeder Klausur.',
        core: ['Das Grundgesetz trennt drei Hoheiten. Gesetzgebung (Art. 105 GG): ausschließlich der Bund bei Zöllen und Finanzmonopolen; konkurrierend bei den übrigen Steuern, wenn ihm das Aufkommen ganz oder teilweise zusteht oder Art. 72 Abs. 2 GG greift; die Länder bei örtlichen Verbrauch- und Aufwandsteuern, solange sie bundesgesetzlich geregelten Steuern nicht gleichartig sind, und beim Steuersatz der Grunderwerbsteuer. Ertrag (Art. 106 GG): Gemeinschaftsteuern sind Einkommen-, Körperschaft- und Umsatzsteuer; Realsteuern (Grund- und Gewerbesteuer) stehen den Gemeinden zu. Verwaltung (Art. 108 GG): Bundesfinanzbehörden für Zölle und bundesgesetzliche Verbrauchsteuern, Landesfinanzbehörden für die übrigen Steuern, die Gemeinden können mit der Verwaltung der Realsteuern betraut werden.',
          'Materiell misst das Verfassungsrecht Steuern vor allem an Art. 3 Abs. 1 GG: Besteuerung nach der Leistungsfähigkeit, horizontale Gleichheit (gleich Leistungsfähige gleich belasten) und vertikale (Leistungsfähigere höher), Folgerichtigkeit bei der Umsetzung einer Belastungsentscheidung, objektives Nettoprinzip (Erwerbsaufwand ist abzugsfähig) und subjektives Nettoprinzip (das Existenzminimum bleibt steuerfrei; daher Grundfreibetrag). Lenkungsteuern sind zulässig, die Lenkung muss aber gleichheitsgerecht ausgestaltet sein und darf nicht erdrosseln; dann ist auch Art. 12 und Art. 14 GG berührt. Art. 6 GG schützt Ehe und Familie (Splitting, Kinderfreibeträge). Im Besteuerungsverfahren wirken Grundrechte als Abwehrrechte, etwa beim Steuergeheimnis (§ 30 AO) und beim informationellen Selbstbestimmungsrecht.'],
        schema: ['Gesetzgebungshoheit: Art. 105 GG', 'Ertragshoheit: Art. 106 GG', 'Verwaltungshoheit: Art. 108 GG', 'Gleichheit: Leistungsfähigkeit, Folgerichtigkeit, Nettoprinzip', 'Lenkungsteuer: Ziel legitim, gleichheitsgerecht, keine Erdrosselung'],
        case: { sv: 'Eine Gemeinde führt eine Steuer auf das Innehaben einer Zweitwohnung ein. Ein Land möchte eine eigene Steuer auf Einkommen über 200.000 € erheben.',
          steps: [['Darf die Gemeinde die Zweitwohnungsteuer regeln?', 'Ja: örtliche Aufwandsteuer (Art. 105 Abs. 2a GG); die Länder übertragen das Satzungsrecht auf die Gemeinden.'], ['Darf das Land eine eigene Einkommensteuer einführen?', 'Nein: Die Einkommensteuer ist bundesgesetzlich geregelt (konkurrierende Gesetzgebung, Bund hat abschließend Gebrauch gemacht); eine gleichartige Landessteuer ist gesperrt.'], ['Wem steht die Einkommensteuer zu?', 'Bund und Ländern gemeinsam, mit Gemeindeanteil (Gemeinschaftsteuer, Art. 106 Abs. 3 und 5 GG).']],
          res: 'Zweitwohnungsteuer zulässig (Aufwandsteuer), Landeseinkommensteuer gesperrt, ESt ist Gemeinschaftsteuer.' },
        nav: [],
        cards: [['Drei Hoheiten der Finanzverfassung und ihre Artikel?', 'Gesetzgebung Art. 105, Ertrag Art. 106, Verwaltung Art. 108 GG.'], ['Was sind Gemeinschaftsteuern?', 'Einkommen-, Körperschaft- und Umsatzsteuer.'], ['Objektives vs. subjektives Nettoprinzip?', 'Objektiv: Erwerbsaufwendungen mindern die Bemessungsgrundlage. Subjektiv: Das Existenzminimum bleibt steuerfrei.'], ['Wo liegt die Grenze einer Lenkungsteuer?', 'Sie muss gleichheitsgerecht sein und darf nicht erdrosseln (sonst Eingriff in Art. 12/14 GG ohne Rechtfertigung).']] },
    ],
    ao: [
      { id: 'a1', t: 'Steuerschuldverhältnis: Entstehen, Fälligkeit, Erlöschen', norms: ['§ 37 AO', '§ 38 AO', '§ 47 AO', '§ 220 AO'], link: 'g2',
        why: 'Der Steueranspruch entsteht kraft Gesetzes, nicht durch den Bescheid. Wer das verstanden hat, versteht Verjährung, Haftung und Erstattung.',
        core: ['Ansprüche aus dem Steuerschuldverhältnis (§ 37 Abs. 1 AO) sind der Steueranspruch, der Steuervergütungsanspruch, der Haftungsanspruch, der Anspruch auf eine steuerliche Nebenleistung und der Erstattungsanspruch. Sie entstehen, sobald der Tatbestand verwirklicht ist, an den das Gesetz die Leistungspflicht knüpft (§ 38 AO). Die Einkommensteuer entsteht mit Ablauf des Veranlagungszeitraums (§ 36 Abs. 1 EStG), Vorauszahlungen mit Beginn des Quartals, die Lohnsteuer mit dem Zufluss des Arbeitslohns. Der Bescheid setzt den Anspruch nur fest (deklaratorisch), er schafft ihn nicht.',
          'Fälligkeit richtet sich nach den Einzelsteuergesetzen, hilfsweise nach § 220 AO (mit Entstehung); die Abschlusszahlung zur Einkommensteuer ist einen Monat nach Bekanntgabe des Bescheids fällig (§ 36 Abs. 4 EStG). Erlöschen (§ 47 AO): durch Zahlung, Aufrechnung, Erlass, Verjährung (Festsetzungs- und Zahlungsverjährung) und Eintritt einer auflösenden Bedingung. Wer ohne rechtlichen Grund gezahlt hat, hat einen Erstattungsanspruch (§ 37 Abs. 2 AO); rechtlicher Grund ist dabei der wirksame Bescheid, nicht die materielle Rechtslage. Steuerliche Nebenleistungen sind etwa Verspätungszuschlag (§ 152), Zinsen (§§ 233 ff.), Säumniszuschlag (§ 240) und Zwangsgeld (§ 329 AO).'],
        schema: ['Anspruchsart (§ 37 AO) bestimmen', 'Entstehung: Tatbestandsverwirklichung (§ 38 AO), bei ESt Ablauf des VZ', 'Festsetzung durch Bescheid (deklaratorisch)', 'Fälligkeit: Einzelsteuergesetz, sonst § 220 AO', 'Erlöschen: Zahlung, Aufrechnung, Erlass, Verjährung (§ 47 AO)'],
        case: { sv: 'Für das Jahr 01 ergibt die Erklärung des T eine Einkommensteuer von 8.400 €. Der Bescheid wird am 20.5.02 bekanntgegeben. T hatte im Jahr 01 Vorauszahlungen von 9.000 € geleistet.',
          steps: [['Wann ist die ESt 01 entstanden?', 'Mit Ablauf des 31.12.01 (§ 36 Abs. 1 EStG i. V. m. § 38 AO).'], ['Was hat T aufgrund des Bescheids?', 'Einen Erstattungsanspruch über 600 € (§ 37 Abs. 2 AO), weil die Vorauszahlungen den festgesetzten Betrag übersteigen.'], ['Durch welchen Tatbestand ist die ESt 01 erloschen?', 'Durch Zahlung (Anrechnung der Vorauszahlungen), § 47 AO.']],
          res: 'Entstehung 31.12.01, Erstattung 600 €, Erlöschen durch Zahlung.' },
        nav: [],
        cards: [['Fünf Ansprüche aus dem Steuerschuldverhältnis?', 'Steuer-, Steuervergütungs-, Haftungs-, Nebenleistungs- und Erstattungsanspruch (§ 37 AO).'], ['Wann entsteht die Einkommensteuer?', 'Mit Ablauf des Veranlagungszeitraums (§ 36 Abs. 1 EStG).'], ['Ist der Steuerbescheid konstitutiv?', 'Nein, er setzt den kraft Gesetzes entstandenen Anspruch nur fest.'], ['Erlöschensgründe nach § 47 AO?', 'Zahlung, Aufrechnung, Erlass, Verjährung, Eintritt einer auflösenden Bedingung.']] },

      { id: 'a2', t: 'Haftung und Haftungsbescheid', norms: ['§ 69 AO', '§ 34 AO', '§ 191 AO', '§ 219 AO'], link: 'a1',
        why: 'Die GmbH zahlt nicht, das Finanzamt nimmt den Geschäftsführer in Anspruch. § 69 AO ist ein Klausurliebling, weil er ein sauberes Prüfschema hat.',
        core: ['Haftung heißt: Jemand steht für eine fremde Steuerschuld ein. Die Haftung ist akzessorisch, setzt also eine bestehende Steuerschuld voraus. Wichtigster Fall ist § 69 AO für die in den §§ 34 und 35 AO genannten Personen, vor allem gesetzliche Vertreter wie GmbH-Geschäftsführer. Tatbestand: 1. Haftungsschuldner aus dem Kreis der §§ 34, 35 AO. 2. Verletzung einer steuerlichen Pflicht (etwa Steuern aus den verwalteten Mitteln zu entrichten, Erklärungen abzugeben). 3. Vorsatz oder grobe Fahrlässigkeit. 4. Kausaler Haftungsschaden: Ansprüche werden nicht oder nicht rechtzeitig festgesetzt oder erfüllt. Bei knappen Mitteln gilt der Grundsatz der anteiligen Tilgung: Der Geschäftsführer haftet nur, soweit er das Finanzamt schlechter behandelt hat als andere Gläubiger; bei der Lohnsteuer hingegen grundsätzlich voll, weil er die Löhne kürzen muss.',
          'Weitere Haftungstatbestände: § 71 AO (Steuerhinterzieher und Gehilfen), § 74 AO (Eigentümer von Gegenständen, die einem Unternehmen dienen, bei wesentlicher Beteiligung über 25 %, für Betriebsteuern), § 75 AO (Betriebsübernehmer). Die Inanspruchnahme erfolgt durch Haftungsbescheid (§ 191 Abs. 1 AO), eine Ermessensentscheidung: Entschließungsermessen (ob) und Auswahlermessen (wer). Die Rechtmäßigkeit prüft man wie üblich: Ermächtigung § 191 AO, formell (Zuständigkeit, Anhörung, Schriftform, Begründung), materiell (keine Verjährung, § 191 Abs. 3 AO; Haftungstatbestand; fehlerfreie Ermessensausübung). Auf Zahlung darf der Haftungsschuldner nach § 219 AO grundsätzlich erst in Anspruch genommen werden, wenn die Vollstreckung beim Steuerschuldner erfolglos war oder aussichtslos ist, außer bei Vorsatz oder bei einbehaltener Lohnsteuer.'],
        schema: ['Ermächtigung: § 191 Abs. 1 AO', 'Formell: Zuständigkeit, Anhörung, Schriftform, Begründung', 'Materiell: keine Festsetzungsverjährung (§ 191 Abs. 3)', '§ 69: Person nach § 34/35, Pflichtverletzung, Vorsatz/grobe Fahrlässigkeit, kausaler Schaden', 'Umfang: anteilige Tilgung (Lohnsteuer: voll)', 'Ermessen: Entschließung und Auswahl fehlerfrei?'],
        case: { sv: 'G ist Geschäftsführer der Z-GmbH, die in Zahlungsschwierigkeiten ist. Im März zahlt G die Löhne voll aus, die einbehaltene Lohnsteuer von 6.000 € führt er nicht ab, weil er Lieferanten bedienen will. Die GmbH wird insolvent.',
          steps: [['Gehört G zum Kreis des § 69 AO?', 'Ja, als gesetzlicher Vertreter der GmbH (§ 34 Abs. 1 AO).'], ['Liegt eine Pflichtverletzung mit grobem Verschulden vor?', 'Ja: Lohnsteuer ist einzubehalten und abzuführen; das bewusste Nichtabführen ist mindestens grob fahrlässig.'], ['In welchem Umfang haftet G?', 'Voll in Höhe von 6.000 €: Bei der Lohnsteuer gilt die anteilige Tilgung nicht; G hätte die Löhne kürzen müssen.']],
          res: 'Haftung nach § 69 i. V. m. § 34 AO über 6.000 €, Haftungsbescheid nach § 191 AO bei fehlerfreiem Ermessen.' },
        nav: [],
        cards: [['Vier Voraussetzungen des § 69 AO?', 'Person nach §§ 34, 35 AO, Pflichtverletzung, Vorsatz oder grobe Fahrlässigkeit, kausaler Haftungsschaden.'], ['Grundsatz der anteiligen Tilgung?', 'Bei knappen Mitteln haftet der Vertreter nur insoweit, wie er das Finanzamt schlechter gestellt hat als andere Gläubiger (nicht bei Lohnsteuer).'], ['Welche Ermessen hat das Finanzamt beim Haftungsbescheid?', 'Entschließungsermessen (ob) und Auswahlermessen (wen).'], ['Was regelt § 219 AO?', 'Zahlungsaufforderung an den Haftungsschuldner grundsätzlich erst nach erfolgloser oder aussichtsloser Vollstreckung beim Steuerschuldner (Ausnahmen: Vorsatz, Lohnsteuer).']] },

      { id: 'a3', t: 'Steuerverwaltungsakt und Bekanntgabe', norms: ['§ 118 AO', '§ 122 AO', '§ 124 AO', '§§ 125–129 AO'], link: 'a1',
        why: 'Ohne wirksame Bekanntgabe kein wirksamer Bescheid, ohne Bekanntgabe keine Einspruchsfrist. Die Viertagesfiktion ist Rechenstoff für jede Fristaufgabe.',
        core: ['Ein Verwaltungsakt ist nach § 118 AO jede Verfügung, Entscheidung oder andere hoheitliche Maßnahme einer Behörde zur Regelung eines Einzelfalls auf dem Gebiet des öffentlichen Rechts mit unmittelbarer Rechtswirkung nach außen. Der Steuerbescheid (§ 155 AO) ist der wichtigste Steuerverwaltungsakt. Er wird mit Bekanntgabe wirksam (§ 124 Abs. 1 AO), und zwar mit dem Inhalt, mit dem er bekanntgegeben wird. Bekanntgabe heißt: mit Willen der Behörde auf den Weg gebracht und dem Adressaten zugegangen. Ein im Inland per Post übermittelter Bescheid gilt nach § 122 Abs. 2 Nr. 1 AO am vierten Tag nach der Aufgabe zur Post als bekanntgegeben (für Aufgaben zur Post ab 2025; davor drei Tage), außer er ist nicht oder später zugegangen; im Zweifel muss die Behörde Zugang und Zeitpunkt nachweisen. Fällt der vierte Tag auf einen Samstag, Sonntag oder Feiertag, verschiebt er sich nach der Rechtsprechung auf den nächsten Werktag.',
          'Fehlerfolgen: Ein besonders schwerwiegender und offenkundiger Fehler macht den Verwaltungsakt nichtig (§ 125 AO), etwa wenn der Adressat nicht erkennbar ist; ein nichtiger Verwaltungsakt ist unwirksam. Sonst ist der fehlerhafte Verwaltungsakt wirksam, aber rechtswidrig und anfechtbar. Verfahrens- und Formfehler können geheilt werden (§ 126 AO, etwa durch nachgeholte Begründung oder Anhörung) oder unbeachtlich sein (§ 127 AO, wenn in der Sache keine andere Entscheidung hätte getroffen werden können; nicht bei Ermessensentscheidungen). Offenbare Unrichtigkeiten wie Schreib- und Rechenfehler darf die Behörde jederzeit berichtigen (§ 129 AO).'],
        schema: ['VA-Merkmale (§ 118): Maßnahme, Behörde, Einzelfall, öffentliches Recht, Außenwirkung, Regelung', 'Bekanntgabe: willentlich auf den Weg gebracht und zugegangen', 'Post im Inland: Fiktion am 4. Tag nach Aufgabe (§ 122 Abs. 2 Nr. 1)', 'Fehler: nichtig (§ 125), sonst rechtswidrig und anfechtbar', 'Heilung (§ 126), Unbeachtlichkeit (§ 127), Berichtigung (§ 129)'],
        case: { sv: 'Das Finanzamt gibt den ESt-Bescheid des P am Montag, 2. Juni 2025, zur Post. P findet ihn am Dienstag, 3. Juni, im Briefkasten. Im Bescheid ist bei der Addition der Einkünfte ein Zahlendreher passiert.',
          steps: [['Wann gilt der Bescheid als bekanntgegeben?', 'Am vierten Tag nach Aufgabe zur Post, also Freitag, 6. Juni 2025 (§ 122 Abs. 2 Nr. 1 AO). Der frühere tatsächliche Zugang ändert nichts.'], ['Wann endet die Einspruchsfrist?', 'Einen Monat nach Bekanntgabe: Ablauf des 7. Juli 2025, weil der 6. Juli ein Sonntag ist (§ 355 Abs. 1, § 108 Abs. 3 AO).'], ['Kann das Finanzamt den Zahlendreher korrigieren?', 'Ja, als offenbare Unrichtigkeit nach § 129 AO, auch nach Ablauf der Einspruchsfrist (innerhalb der Festsetzungsfrist).']],
          res: 'Bekanntgabe 6.6.2025, Fristende 7.7.2025, Berichtigung nach § 129 AO.' },
        nav: [],
        cards: [['Merkmale des Verwaltungsakts nach § 118 AO?', 'Hoheitliche Maßnahme einer Behörde zur Regelung eines Einzelfalls auf dem Gebiet des öffentlichen Rechts mit unmittelbarer Außenwirkung.'], ['Bekanntgabefiktion bei Postversand im Inland?', 'Vierter Tag nach Aufgabe zur Post (§ 122 Abs. 2 Nr. 1 AO), außer bei späterem oder fehlendem Zugang.'], ['Nichtigkeit nach § 125 AO?', 'Besonders schwerwiegender Fehler, der bei verständiger Würdigung offenkundig ist; Folge: unwirksam.'], ['Was erlaubt § 129 AO?', 'Berichtigung offenbarer Unrichtigkeiten (Schreib-, Rechenfehler) jederzeit innerhalb der Festsetzungsfrist.']] },

      { id: 'a4', t: 'Festsetzungsverfahren: Pflichten und Zuschläge', norms: ['§ 90 AO', '§ 149 AO', '§ 152 AO', '§ 240 AO', '§§ 193 ff. AO'], link: 'a3',
        why: 'Wer zu spät erklärt oder zu spät zahlt, bekommt Zuschläge. Beide lassen sich ausrechnen, und beide werden gern verwechselt.',
        core: ['Im Besteuerungsverfahren gilt der Untersuchungsgrundsatz (§ 88 AO): Das Finanzamt ermittelt den Sachverhalt von Amts wegen. Der Steuerpflichtige hat Mitwirkungspflichten (§ 90 AO), insbesondere die Pflicht zur Abgabe von Steuererklärungen (§ 149 AO). Für die Einkommensteuer gilt grundsätzlich: Erklärung bis zum Ablauf des siebten Monats nach dem Besteuerungszeitraum, also 31. Juli; bei Beratung durch Steuerberater später. Verletzt das Finanzamt seine Ermittlungspflicht, während der Steuerpflichtige seine Mitwirkungspflichten erfüllt hat, kann es später nicht auf neue Tatsachen ändern (Treu und Glauben bei § 173 AO). Die Außenprüfung (§§ 193 ff. AO) ist das wichtigste Ermittlungsinstrument; nach ihr gilt die erhöhte Bestandskraft des § 173 Abs. 2 AO.',
          'Verspätungszuschlag (§ 152 AO) für verspätete Erklärungen: grundsätzlich Ermessen, zwingend, wenn die Erklärung nicht binnen 14 Monaten nach Ablauf des Kalenderjahres abgegeben wird. Höhe: für jeden angefangenen Monat der Verspätung 0,25 % der festgesetzten Steuer abzüglich Vorauszahlungen und Anrechnungsbeträge, mindestens 10 € je angefangenem Monat, höchstens 25.000 €. Säumniszuschlag (§ 240 AO) für verspätete Zahlung: kraft Gesetzes 1 % des auf volle 50 € abgerundeten rückständigen Betrags für jeden angefangenen Monat der Säumnis. Bei Überweisung gibt es eine Schonfrist von drei Tagen, bei Scheck oder Barzahlung nicht. Hinterziehung (§ 370 AO, Vorsatz) und leichtfertige Steuerverkürzung (§ 378 AO, Ordnungswidrigkeit) verlängern die Festsetzungsfrist auf 10 bzw. 5 Jahre.'],
        schema: ['Untersuchungsgrundsatz (§ 88) und Mitwirkung (§ 90)', 'Erklärungsfrist (§ 149): grds. 31.7. des Folgejahres', 'Verspätungszuschlag (§ 152): 0,25 % je angefangenem Monat, mind. 10 €/Monat', 'Säumniszuschlag (§ 240): 1 % je angefangenem Monat auf 50 € abgerundet', 'Außenprüfung (§§ 193 ff.) und erhöhte Bestandskraft (§ 173 Abs. 2)'],
        case: { sv: 'S muss ihre ESt-Erklärung 01 bis 31.7.02 abgeben und gibt sie am 20.10.02 ab. Festgesetzt werden 6.000 €, Vorauszahlungen waren 2.000 €. Die Abschlusszahlung von 4.000 € ist am 15.12.02 fällig; S überweist erst am 20.2.03.',
          steps: [['Wie viele angefangene Monate der Verspätung?', 'Vom 1.8. bis 20.10.: drei angefangene Monate.'], ['Verspätungszuschlag, wenn das Finanzamt ihn festsetzt?', '0,25 % · (6.000 − 2.000) = 10 € je Monat; das ist genau der Mindestbetrag: 3 · 10 € = 30 €.'], ['Säumniszuschlag?', 'Vom 16.12.02 bis 20.2.03 sind drei angefangene Monate (Schonfrist reicht nicht): 1 % · 4.000 · 3 = 120 €.']],
          res: 'Verspätungszuschlag 30 €, Säumniszuschlag 120 €.' },
        nav: [],
        cards: [['Verspätungszuschlag: Höhe?', '0,25 % der festgesetzten Steuer (abzüglich Vorauszahlungen und Anrechnungen) für jeden angefangenen Monat, mindestens 10 € je Monat, höchstens 25.000 €.'], ['Wann ist der Verspätungszuschlag zwingend?', 'Bei Abgabe nach mehr als 14 Monaten nach Ablauf des Kalenderjahres (§ 152 Abs. 2 AO), mit Ausnahmen.'], ['Säumniszuschlag: Höhe?', '1 % des auf 50 € abgerundeten Rückstands je angefangenem Monat.'], ['Schonfrist beim Säumniszuschlag?', 'Drei Tage bei Überweisung, nicht bei Scheck oder Barzahlung.']] },

      { id: 'a5', t: 'Festsetzungsverjährung', norms: ['§ 169 AO', '§ 170 AO', '§ 171 AO'], link: 'a4',
        why: 'Der erste Prüfpunkt der materiellen Rechtmäßigkeit. Beginn, Dauer und Hemmung sauber durchzählen, und die Klausur hat ihre erste sichere Punktekiste.',
        core: ['Nach Ablauf der Festsetzungsfrist ist eine Festsetzung, Aufhebung oder Änderung nicht mehr zulässig (§ 169 Abs. 1 AO); der Anspruch erlischt (§ 47 AO). Dauer (§ 169 Abs. 2 AO): ein Jahr für Verbrauchsteuern, vier Jahre für die übrigen Steuern, fünf Jahre bei leichtfertiger Verkürzung, zehn bei Hinterziehung. Beginn (§ 170 Abs. 1 AO): mit Ablauf des Kalenderjahres, in dem die Steuer entstanden ist. Anlaufhemmung (§ 170 Abs. 2 Nr. 1 AO): Ist eine Steuererklärung einzureichen, beginnt die Frist erst mit Ablauf des Jahres der Einreichung, spätestens mit Ablauf des dritten Kalenderjahres nach Entstehung.',
          'Ablaufhemmungen (§ 171 AO) schieben das Ende hinaus: etwa solange über einen Einspruch nicht entschieden ist (Abs. 3a), bei einer begonnenen Außenprüfung (Abs. 4), und bei Grundlagenbescheiden (Abs. 10): Die Frist für den Folgebescheid endet nicht vor Ablauf von zwei Jahren nach Bekanntgabe des Grundlagenbescheids. Bei der Antragsveranlagung eines Arbeitnehmers (§ 46 Abs. 2 Nr. 8 EStG) besteht keine Erklärungspflicht, also keine Anlaufhemmung: Die Frist beginnt mit Ablauf des Entstehungsjahres. Die Frist ist gewahrt, wenn der Bescheid vor ihrem Ablauf den Bereich des Finanzamts verlassen hat (§ 169 Abs. 1 S. 3 Nr. 1 AO).'],
        schema: ['Entstehung der Steuer (ESt: 31.12. des VZ)', 'Beginn: Ablauf des Entstehungsjahres (§ 170 Abs. 1)', 'Anlaufhemmung bei Erklärungspflicht: Jahr der Abgabe, max. 3 Jahre (§ 170 Abs. 2 Nr. 1)', 'Dauer: 1/4/5/10 Jahre (§ 169 Abs. 2)', 'Ablaufhemmungen prüfen (§ 171), z. B. Abs. 10 Grundlagenbescheid', 'Ende: 31.12. des letzten Jahres'],
        case: { sv: 'Für die ESt 2019 bestand eine Erklärungspflicht. K gab die Erklärung im Juni 2021 ab. Ein geänderter Bescheid soll im Mai 2026 ergehen.',
          steps: [['Wann begann die Festsetzungsfrist?', 'Anlaufhemmung: mit Ablauf des Jahres der Abgabe, also am 31.12.2021.'], ['Wann endet sie regulär?', 'Vier Jahre später, mit Ablauf des 31.12.2025.'], ['Ist die Änderung im Mai 2026 zulässig?', 'Nur bei einer Ablaufhemmung (etwa § 171 Abs. 10 AO) oder bei Hinterziehung (10 Jahre) bzw. Leichtfertigkeit (5 Jahre); sonst Festsetzungsverjährung.']],
          res: 'Beginn 31.12.2021, Ende 31.12.2025; Änderung 2026 nur mit Hemmung oder längerer Frist.' },
        nav: [],
        cards: [['Dauer der Festsetzungsfrist?', 'Verbrauchsteuern 1, übrige Steuern 4, leichtfertige Verkürzung 5, Hinterziehung 10 Jahre.'], ['Anlaufhemmung nach § 170 Abs. 2 Nr. 1 AO?', 'Bei Erklärungspflicht beginnt die Frist mit Ablauf des Jahres der Einreichung, spätestens mit Ablauf des dritten Jahres nach Entstehung.'], ['Ablaufhemmung bei Grundlagenbescheiden?', 'Frist für den Folgebescheid endet nicht vor Ablauf von zwei Jahren nach Bekanntgabe des Grundlagenbescheids (§ 171 Abs. 10 AO).'], ['Anlaufhemmung bei Antragsveranlagung?', 'Keine, weil keine Erklärungspflicht besteht; Beginn mit Ablauf des Entstehungsjahres.']] },

      { id: 'a6', t: 'Vorbehalt, Vorläufigkeit, Grundlagen- und Folgebescheid', norms: ['§ 164 AO', '§ 165 AO', '§§ 179–182 AO', '§ 175 Abs. 1 Nr. 1 AO'], link: 'a5',
        why: 'Feststellungsbescheid der KG, Gewerbesteuermessbescheid, ESt-Bescheid: Wer weiß, welcher Bescheid welchen bindet, löst die schweren Verfahrensfälle.',
        core: ['Nebenbestimmungen: Unter dem Vorbehalt der Nachprüfung (§ 164 AO) kann eine Steuer festgesetzt werden, solange der Fall nicht abschließend geprüft ist; die Festsetzung ist dann jederzeit in vollem Umfang änderbar, solange die Festsetzungsfrist läuft. Der Vorbehalt entfällt mit Ablauf der regulären Festsetzungsfrist. Vorläufig (§ 165 AO) setzt das Finanzamt fest, soweit ungewiss ist, ob die Voraussetzungen für die Entstehung einer Steuer eingetreten sind, oder soweit ein Musterverfahren zur Verfassungsmäßigkeit anhängig ist; änderbar nur im Umfang der Vorläufigkeit.',
          'Feststellungsbescheide stellen Besteuerungsgrundlagen gesondert fest (§ 179 AO), bei mehreren Beteiligten gesondert und einheitlich, etwa die Einkünfte einer Mitunternehmerschaft (§ 180 Abs. 1 S. 1 Nr. 2 Buchst. a AO). Sie sind Grundlagenbescheide und binden die Folgebescheide (§ 182 Abs. 1 AO), etwa den ESt-Bescheid des Gesellschafters. Auch der Gewerbesteuermessbescheid des Finanzamts (§ 184 AO) ist Grundlagenbescheid für den Gewerbesteuerbescheid der Gemeinde. Liegt der Grundlagenbescheid noch nicht vor, darf geschätzt werden (§ 155 Abs. 2, § 162 Abs. 5 AO). Ergeht oder ändert sich der Grundlagenbescheid, ist der Folgebescheid anzupassen (§ 175 Abs. 1 S. 1 Nr. 1 AO), auch zum Nachteil; die Ablaufhemmung des § 171 Abs. 10 AO sichert das ab. Einwendungen gegen den Grundlagenbescheid kann man nur gegen ihn selbst vorbringen, nicht gegen den Folgebescheid (§ 351 Abs. 2 AO).'],
        schema: ['Nebenbestimmung im Bescheid? § 164 (voll änderbar) / § 165 (soweit vorläufig)', 'Gibt es einen Grundlagenbescheid (Feststellung, Messbescheid)?', 'Bindung: § 182 Abs. 1 AO', 'Anpassung des Folgebescheids: § 175 Abs. 1 Nr. 1 AO', 'Frist: § 171 Abs. 10 AO (zwei Jahre nach Bekanntgabe)', 'Rechtsschutz: gegen den Grundlagenbescheid (§ 351 Abs. 2)'],
        case: { sv: 'L ist Kommanditistin der M-KG. Ihr ESt-Bescheid 01 ergeht, bevor die Feststellung der KG vorliegt; das Finanzamt schätzt ihren Anteil auf 9.000 €. Ein Jahr später stellt das zuständige Finanzamt für L einen Anteil von 14.000 € fest. L meint, ihr ESt-Bescheid sei bestandskräftig.',
          steps: [['Durfte das Finanzamt schätzen?', 'Ja, § 162 Abs. 5 i. V. m. § 155 Abs. 2 AO erlaubt die Schätzung von Besteuerungsgrundlagen, die in einem Grundlagenbescheid festzustellen sind.'], ['Auf welcher Grundlage wird der ESt-Bescheid geändert?', '§ 175 Abs. 1 S. 1 Nr. 1 AO: Der Feststellungsbescheid ist Grundlagenbescheid und bindet (§ 182 Abs. 1 AO); die Bestandskraft hindert nicht.'], ['Wie kann L die 14.000 € angreifen?', 'Nur durch Einspruch gegen den Feststellungsbescheid, nicht gegen den angepassten ESt-Bescheid (§ 351 Abs. 2 AO).']],
          res: 'Schätzung zulässig, Anpassung nach § 175 Abs. 1 Nr. 1 AO auf 14.000 €, Rechtsschutz gegen den Feststellungsbescheid.' },
        nav: [],
        cards: [['Wirkung des Vorbehalts der Nachprüfung?', 'Festsetzung jederzeit in vollem Umfang änderbar, bis der Vorbehalt mit Ablauf der Festsetzungsfrist entfällt.'], ['Vorläufige Festsetzung (§ 165 AO)?', 'Bei Ungewissheit über Entstehungsvoraussetzungen oder anhängigen Musterverfahren; änderbar nur soweit vorläufig.'], ['Welche Norm passt den Folgebescheid an einen Grundlagenbescheid an?', '§ 175 Abs. 1 S. 1 Nr. 1 AO (Bindung nach § 182 Abs. 1 AO).'], ['Gewerbesteuermessbescheid und Gewerbesteuerbescheid?', 'Der Messbescheid des Finanzamts ist Grundlagenbescheid für den Gewerbesteuerbescheid der Gemeinde.']] },

      { id: 'a7', t: 'Änderung von Steuerbescheiden', norms: ['§ 172 AO', '§ 173 AO', '§ 175 AO', '§ 177 AO'], link: 'a6',
        why: 'Bestandskraft ist der Normalfall, die Änderung die Ausnahme mit Tatbestand. Die Prüfungsreihenfolge und § 173 AO sind die wichtigste Verfahrensklausur des Moduls.',
        core: ['Es gibt kein allgemeines Änderungsrecht: Ein bestandskräftiger Bescheid darf nur geändert werden, soweit ein Änderungstatbestand greift (§ 172 Abs. 1 AO). Reihenfolge: zuerst Nebenbestimmungen (§§ 164, 165 AO), dann die schlichte Änderung (§ 172 Abs. 1 S. 1 Nr. 2 Buchst. a AO: mit Zustimmung oder auf Antrag; zugunsten nur, wenn der Antrag innerhalb der Einspruchsfrist gestellt wird), dann die besonderen Tatbestände. Faustregel zur Abgrenzung: Hat ein Umstand schon bei Erlass bestanden und wurde er erst später bekannt, ist § 173 AO einschlägig; tritt er erst nach Erlass ein und wirkt steuerlich zurück, § 175 Abs. 1 S. 1 Nr. 2 AO; ist es ein Grundlagenbescheid, § 175 Abs. 1 S. 1 Nr. 1 AO.',
          '§ 173 Abs. 1 Nr. 1 AO: Tatsachen oder Beweismittel, die nachträglich bekanntwerden und zu einer höheren Steuer führen. Tatsache ist alles, was Merkmal eines gesetzlichen Tatbestands sein kann (Zustände, Vorgänge, Beziehungen); keine Tatsache sind Schlussfolgerungen und rechtliche Bewertungen. Nachträglich heißt: nach der abschließenden Zeichnung des Bescheids und dem zuständigen Bearbeiter nicht bekannt. Nach Treu und Glauben ist die Änderung ausgeschlossen, wenn das Finanzamt seine Ermittlungspflicht verletzt und der Steuerpflichtige seine Mitwirkungspflicht erfüllt hat. § 173 Abs. 1 Nr. 2 AO: Tatsachen, die zu einer niedrigeren Steuer führen, nur ohne grobes Verschulden des Steuerpflichtigen. Nach einer Außenprüfung ist eine Änderung nach § 173 Abs. 1 AO nur bei Hinterziehung oder leichtfertiger Verkürzung möglich (Abs. 2). § 177 AO erlaubt bei jeder Änderung, materielle Fehler im Rahmen des Änderungsspielraums mitzuberichtigen. Geändert wird immer nur „soweit“ der Tatbestand reicht (Punktberichtigung).'],
        schema: ['§§ 164, 165 vorrangig', '§ 172 Abs. 1 Nr. 2a: Antrag/Zustimmung', 'Umstand vor Erlass, später bekannt: § 173', 'Umstand nach Erlass mit Rückwirkung: § 175 Abs. 1 Nr. 2', 'Grundlagenbescheid: § 175 Abs. 1 Nr. 1', '§ 173 Nr. 1: Tatsache, nachträglich bekannt, höhere Steuer, keine Ermittlungsfehler-Sperre', '§ 173 Nr. 2: niedrigere Steuer, kein grobes Verschulden', 'Umfang: soweit; Mitberichtigung § 177'],
        case: { sv: 'Nach Bestandskraft des ESt-Bescheids erfährt das Finanzamt aus einer Kontrollmitteilung, dass Arbeitnehmer R im Veranlagungsjahr verbilligt Anteile an seinem Arbeitgeber erworben hat (Vorteil 30.000 €). R hatte den Vorgang nicht erklärt; der Bearbeiter kannte ihn nicht.',
          steps: [['Welche Änderungsnorm?', '§ 173 Abs. 1 Nr. 1 AO: Der Erwerb hat schon vor Erlass stattgefunden und ist erst später bekannt geworden.'], ['Ist der verbilligte Erwerb eine Tatsache?', 'Ja, ein Vorgang, der den Tatbestand des § 19 EStG (geldwerter Vorteil aus dem Dienstverhältnis) erfüllen kann. Die Einordnung als Arbeitslohn ist die rechtliche Würdigung dazu.'], ['Führt sie zu einer höheren Steuer und ist die Änderung gesperrt?', 'Höhere Steuer ja (30.000 € mehr Arbeitslohn). Keine Sperre: R hat seine Mitwirkungspflicht verletzt, das Finanzamt hatte keinen Anlass zur Ermittlung.']],
          res: 'Änderung nach § 173 Abs. 1 Nr. 1 AO zulässig, soweit der Vorteil von 30.000 € reicht.' },
        nav: [],
        cards: [['Prüfungsreihenfolge der Änderungsnormen?', '§§ 164, 165, dann § 172 Abs. 1 Nr. 2a, dann §§ 173 ff.'], ['Tatsache im Sinne des § 173 AO?', 'Alles, was Merkmal oder Teilstück eines gesetzlichen Tatbestands sein kann; nicht Schlussfolgerungen und rechtliche Bewertungen.'], ['Wann ist § 173 Abs. 1 Nr. 1 AO trotz neuer Tatsache gesperrt?', 'Wenn das Finanzamt seine Ermittlungspflicht verletzt und der Steuerpflichtige seine Mitwirkungspflicht erfüllt hat (Treu und Glauben); nach Außenprüfung (Abs. 2) außer bei Hinterziehung/Leichtfertigkeit.'], ['§ 173 vs. § 175 Abs. 1 Nr. 2 AO?', '§ 173: Umstand lag schon bei Erlass vor. § 175 Nr. 2: Ereignis tritt danach ein und wirkt steuerlich zurück.']] },

      { id: 'a8', t: 'Einspruch und Klage', norms: ['§§ 347 ff. AO', '§ 355 AO', '§ 40 FGO', '§ 47 FGO'], link: 'a7',
        why: 'Zwei der vier Klausurkonstellationen beginnen mit der Zulässigkeit. Die Prüfpunkte sind kurz, bringen aber sichere Punkte, und die Fristen lassen sich rechnen.',
        core: ['Einspruch: Statthaft gegen Verwaltungsakte in Abgabenangelegenheiten (§ 347 Abs. 1 AO), nicht in den Fällen des § 348 AO. Beschwer (§ 350 AO): Der Einspruchsführer muss geltend machen, durch den Verwaltungsakt beschwert zu sein; bei Steuerbescheiden ergibt sie sich in der Regel aus der Höhe der festgesetzten Steuer, nicht aus einzelnen Besteuerungsgrundlagen. Frist (§ 355 Abs. 1 AO): ein Monat nach Bekanntgabe; ohne oder mit unrichtiger Rechtsbehelfsbelehrung ein Jahr (§ 356 Abs. 2 AO); bei unverschuldeter Versäumnis Wiedereinsetzung (§ 110 AO). Form (§ 357 AO): schriftlich oder elektronisch; eine falsche Bezeichnung schadet nicht. Besonderheiten: Änderungsbescheide sind nur anfechtbar, soweit die Änderung reicht (§ 351 Abs. 1 AO); Folgebescheide nicht mit Einwendungen gegen den Grundlagenbescheid (§ 351 Abs. 2 AO). Das Finanzamt prüft den Fall in vollem Umfang neu und darf nach Hinweis auch verbösern (§ 367 Abs. 2 S. 2 AO).',
          'Klage vor dem Finanzgericht: Finanzrechtsweg (§ 33 FGO), statthafte Klageart (Anfechtungsklage nach § 40 Abs. 1 FGO gegen einen belastenden Verwaltungsakt, Verpflichtungsklage auf Erlass eines abgelehnten Verwaltungsakts), Klagebefugnis (§ 40 Abs. 2 FGO), erfolgloses Vorverfahren (§ 44 FGO; Ausnahmen: Sprungklage mit Zustimmung der Behörde nach § 45 FGO, Untätigkeitsklage nach § 46 FGO), Klagefrist ein Monat nach Bekanntgabe der Einspruchsentscheidung (§ 47 FGO). Die Klage ist begründet, soweit der Verwaltungsakt rechtswidrig ist und den Kläger in seinen Rechten verletzt (§ 100 Abs. 1 FGO). Weder Einspruch noch Klage hemmen die Vollziehung; dafür gibt es die Aussetzung der Vollziehung (§ 361 AO, § 69 FGO).'],
        schema: ['Einspruch: Statthaftigkeit (§ 347), Beschwer (§ 350), Frist (§ 355), Form (§ 357)', 'Sonderfälle: § 351 Abs. 1 (Änderungsbescheid), Abs. 2 (Folgebescheid)', 'Klage: Rechtsweg (§ 33), Klageart (§ 40 Abs. 1), Klagebefugnis (§ 40 Abs. 2)', 'Vorverfahren (§ 44), Frist (§ 47 FGO)', 'Begründetheit: rechtswidrig und Rechtsverletzung (§ 100 FGO)'],
        case: { sv: 'Gegen ihren ESt-Bescheid, der ihr am Freitag, 7. März bekanntgegeben wurde, legt V am Montag, 7. April per E-Mail an das Finanzamt Einspruch ein und nennt ihn „Widerspruch“. Sie rügt eine zu hoch angesetzte Einnahme.',
          steps: [['Ist der Einspruch statthaft?', 'Ja, gegen einen Steuerbescheid in Abgabenangelegenheiten (§ 347 Abs. 1 AO); die falsche Bezeichnung schadet nicht (§ 357 Abs. 1 AO).'], ['Frist gewahrt?', 'Ja: Ein Monat nach dem 7. März endet am 7. April (§ 355 Abs. 1, § 108 Abs. 1 AO i. V. m. § 188 Abs. 2 BGB); der 7. April ist ein Werktag.'], ['Ist V beschwert?', 'Ja, die zu hohe Einnahme führt zu einer zu hohen Steuer (§ 350 AO).']],
          res: 'Zulässiger Einspruch: statthaft, fristgerecht, formgerecht (elektronisch), Beschwer gegeben.' },
        nav: [],
        cards: [['Zulässigkeitsvoraussetzungen des Einspruchs?', 'Statthaftigkeit (§ 347), Beschwer (§ 350), Frist (§ 355), Form (§ 357), ggf. § 351.'], ['Einspruchsfrist ohne Rechtsbehelfsbelehrung?', 'Ein Jahr (§ 356 Abs. 2 AO).'], ['Prüfpunkte der Anfechtungsklage?', 'Finanzrechtsweg, Klageart § 40 Abs. 1 FGO, Klagebefugnis, erfolgloses Vorverfahren, Klagefrist ein Monat (§ 47 FGO).'], ['Hemmt der Einspruch die Zahlungspflicht?', 'Nein; dafür braucht es Aussetzung der Vollziehung (§ 361 AO).']] },
    ],
    est: [
      { id: 'e1', t: 'Persönliche Steuerpflicht', norms: ['§ 1 EStG', '§ 8 AO', '§ 9 AO', '§ 49 EStG'], link: 'g1',
        why: 'Jede materielle ESt-Prüfung beginnt mit der Frage: Ist die Person in Deutschland steuerpflichtig, und wenn ja, mit welchen Einkünften?',
        core: ['Unbeschränkt einkommensteuerpflichtig sind natürliche Personen mit Wohnsitz oder gewöhnlichem Aufenthalt im Inland (§ 1 Abs. 1 EStG). Wohnsitz (§ 8 AO): Jemand hat eine Wohnung unter Umständen inne, die darauf schließen lassen, dass er sie beibehalten und benutzen wird. Es genügt eine jederzeit verfügbare, eingerichtete Wohnung, die regelmäßig, wenn auch nicht ständig, genutzt wird; man kann mehrere Wohnsitze haben, auch im Ausland, und die Staatsangehörigkeit spielt keine Rolle. Gewöhnlicher Aufenthalt (§ 9 AO): Aufenthalt unter Umständen, die erkennen lassen, dass er nicht nur vorübergehend ist; ein zusammenhängender Aufenthalt von mehr als sechs Monaten genügt stets, kurzfristige Unterbrechungen bleiben unberücksichtigt.',
          'Rechtsfolge der unbeschränkten Steuerpflicht ist das Welteinkommensprinzip: Alle in- und ausländischen Einkünfte werden erfasst; Doppelbesteuerungsabkommen können das Besteuerungsrecht beschränken (Freistellung mit Progressionsvorbehalt oder Anrechnung). Beschränkt steuerpflichtig (§ 1 Abs. 4 EStG) sind Personen ohne Wohnsitz und gewöhnlichen Aufenthalt im Inland mit inländischen Einkünften im Sinne des § 49 EStG; viele werden durch Steuerabzug abgegolten (§ 50 Abs. 2 EStG), persönliche Abzüge wie Grundfreibetrag und Splitting entfallen weitgehend. Auf Antrag kann eine Person mit nahezu allen Einkünften im Inland (90 % oder unter dem Grundfreibetrag) als unbeschränkt steuerpflichtig behandelt werden (§ 1 Abs. 3 EStG).'],
        schema: ['Natürliche Person?', 'Wohnsitz im Inland (§ 8 AO)?', 'Sonst gewöhnlicher Aufenthalt (§ 9 AO, > 6 Monate)?', 'Rechtsfolge: Welteinkommen, DBA prüfen', 'Sonst beschränkt: nur inländische Einkünfte (§ 49 EStG)'],
        case: { sv: 'J, Deutscher, arbeitet seit Jahren als Berater in Singapur und hat dort seine Familienwohnung. In Leipzig behält er eine möblierte Zweizimmerwohnung mit Kleidung und Unterlagen, die er etwa fünfmal im Jahr für einige Tage nutzt. Sonst steht sie leer.',
          steps: [['Hat J einen Wohnsitz im Inland?', 'Ja: Er hat die eingerichtete Wohnung jederzeit zur Verfügung und nutzt sie regelmäßig. Das genügt für § 8 AO, auch neben einem Wohnsitz im Ausland.'], ['Folge?', 'Unbeschränkte Steuerpflicht nach § 1 Abs. 1 EStG mit dem Welteinkommen.'], ['Was regelt das DBA in dieser Lage?', 'Welcher Staat für welche Einkünfte besteuern darf; Deutschland stellt etwa frei (mit Progressionsvorbehalt) oder rechnet ausländische Steuer an.']],
          res: 'Inländischer Wohnsitz, unbeschränkte Steuerpflicht, Welteinkommen mit DBA-Schranken.' },
        nav: [],
        cards: [['Wohnsitz nach § 8 AO?', 'Wohnung, die jemand unter Umständen innehat, die auf Beibehaltung und Benutzung schließen lassen.'], ['Gewöhnlicher Aufenthalt nach § 9 AO?', 'Nicht nur vorübergehender Aufenthalt; stets bei mehr als sechs Monaten zusammenhängend.'], ['Rechtsfolge der unbeschränkten Steuerpflicht?', 'Welteinkommensprinzip (Schranken durch DBA).'], ['Beschränkte Steuerpflicht?', 'Kein Wohnsitz und gewöhnlicher Aufenthalt im Inland, aber inländische Einkünfte nach § 49 EStG.']] },

      { id: 'e2', t: 'Das Schema des § 2 EStG und die Liebhaberei', norms: ['§ 2 EStG', 'Einkünfteerzielungsabsicht', 'Dualismus'], link: 'e1',
        why: 'Konstellation vier der Klausur fragt genau nach diesen Begriffen. Wer das Schema im Schlaf kann, hat die Gliederung, bevor er den Sachverhalt zu Ende gelesen hat.',
        core: ['Der Einkommensteuer unterliegen nur Einkünfte aus den sieben Einkunftsarten (§ 2 Abs. 1 EStG): Land- und Forstwirtschaft, Gewerbebetrieb, selbständige Arbeit, nichtselbständige Arbeit, Kapitalvermögen, Vermietung und Verpachtung, sonstige Einkünfte (§ 22). Was in keine Einkunftsart fällt, ist nicht steuerbar (etwa Lottogewinne, Erbschaften, Schenkungen). Dualismus (§ 2 Abs. 2 EStG): Bei den ersten drei Arten ist der Gewinn maßgeblich (Reinvermögenszugangstheorie, auch Wertsteigerungen im Betriebsvermögen sind erfasst), bei den letzten vier der Überschuss der Einnahmen über die Werbungskosten (Quellentheorie, Veräußerung der Quelle grundsätzlich nicht steuerbar, außer §§ 17, 20 Abs. 2, 23 EStG).',
          'Schema: Einkünfte aus jeder Einkunftsart, Summe der Einkünfte (Verlustausgleich), abzüglich Altersentlastungsbetrag, Entlastungsbetrag für Alleinerziehende und Freibetrag für Land- und Forstwirte ergibt den Gesamtbetrag der Einkünfte (GdE); abzüglich Verlustabzug (§ 10d), Sonderausgaben (§§ 10 ff.) und außergewöhnlicher Belastungen (§§ 33 ff.) das Einkommen; abzüglich Freibeträge für Kinder (wenn günstiger als Kindergeld) und Härteausgleich das zu versteuernde Einkommen (zvE). Darauf wird der Tarif angewendet. Jede Einkunftsart setzt Einkünfteerzielungsabsicht voraus: die Absicht, über die Gesamtdauer der Betätigung einen Totalgewinn oder Totalüberschuss zu erzielen. Fehlt sie, liegt Liebhaberei vor; Verluste werden dann nicht berücksichtigt. Anzeichen: dauerhafte Verluste, keine Reaktion darauf, persönliche Motive (Hobby).'],
        schema: ['Einkunftsart (sieben, § 2 Abs. 1)?', 'Einkünfteerzielungsabsicht (sonst Liebhaberei)', 'Gewinn (Nr. 1–3) oder Überschuss (Nr. 4–7)', 'Summe der Einkünfte', '− Altersentlastung, Alleinerziehende, LuF-Freibetrag = GdE', '− Verlustabzug, Sonderausgaben, agB = Einkommen', '− Kinderfreibeträge, Härteausgleich = zvE'],
        case: { sv: 'Zahnärztin D züchtet seit zwölf Jahren Rennpferde. Jedes Jahr entsteht ein Verlust von 20.000 bis 30.000 €, ein Gewinn ist nicht absehbar; D ändert nichts am Konzept und nennt die Pferde ihre Leidenschaft. Daneben erzielt sie 140.000 € Gewinn aus ihrer Praxis.',
          steps: [['Welche Einkunftsart hat die Praxis?', 'Selbständige Arbeit (§ 18 EStG), freier Beruf; Gewinneinkunftsart.'], ['Sind die Pferdeverluste ausgleichsfähig?', 'Nein: Ohne Totalgewinnprognose und mit persönlichen Motiven fehlt die Gewinnerzielungsabsicht; Liebhaberei, nicht steuerbar.'], ['Summe der Einkünfte?', '140.000 € (nur die Praxis).']],
          res: 'Pferdezucht ist Liebhaberei, Summe der Einkünfte 140.000 €.' },
        nav: [],
        cards: [['Sieben Einkunftsarten?', 'LuF, Gewerbebetrieb, selbständige Arbeit, nichtselbständige Arbeit, Kapitalvermögen, VuV, sonstige Einkünfte.'], ['Gewinn- und Überschusseinkünfte?', 'Gewinn: §§ 13, 15, 18. Überschuss: §§ 19, 20, 21, 22.'], ['Von der Summe der Einkünfte zum GdE?', 'Abzug von Altersentlastungsbetrag, Entlastungsbetrag für Alleinerziehende und LuF-Freibetrag.'], ['Liebhaberei?', 'Betätigung ohne Absicht eines Totalgewinns/Totalüberschusses; Verluste bleiben unberücksichtigt.']] },

      { id: 'e3', t: 'Überschusseinkünfte: Einnahmen, Werbungskosten, Zufluss', norms: ['§ 8 EStG', '§ 9 EStG', '§ 12 EStG', '§ 11 EStG'], link: 'e2',
        why: 'Die Begriffe Einnahme, Werbungskosten und Zufluss tragen alle Überschusseinkünfte. Gemischte Aufwendungen sind der Klassiker für Abgrenzungspunkte.',
        core: ['Einnahmen sind alle Güter in Geld oder Geldeswert, die dem Steuerpflichtigen im Rahmen einer Überschusseinkunftsart zufließen (§ 8 Abs. 1 EStG). Sachbezüge werden mit dem um übliche Preisnachlässe geminderten üblichen Endpreis am Abgabeort bewertet (§ 8 Abs. 2 S. 1 EStG); eine Freigrenze von 50 € im Monat gilt für bestimmte Sachbezüge. Werbungskosten sind Aufwendungen zur Erwerbung, Sicherung und Erhaltung der Einnahmen (§ 9 Abs. 1 EStG); entscheidend ist die Veranlassung durch die Einkunftserzielung. Ohne Nachweis gelten Pauschbeträge (§ 9a EStG), etwa der Arbeitnehmer-Pauschbetrag von derzeit 1.230 €. Bei Kapitaleinkünften gibt es statt Werbungskosten nur den Sparer-Pauschbetrag (§ 20 Abs. 9 EStG).',
          'Kosten der Lebensführung sind nicht abziehbar (§ 12 Nr. 1 EStG), auch wenn sie den Beruf fördern. Gemischte Aufwendungen werden seit der Entscheidung des Großen Senats des BFH von 2009 nach objektiven Kriterien aufgeteilt (etwa nach Zeitanteilen); nur bei untergeordneter privater oder beruflicher Mitveranlassung (unter 10 %) gilt alles oder nichts, und bei untrennbarer Vermischung gar kein Abzug. Spezialregeln gehen vor, etwa für Fahrten zwischen Wohnung und erster Tätigkeitsstätte (Entfernungspauschale) oder das häusliche Arbeitszimmer. Zeitlich gilt das Zufluss- und Abflussprinzip (§ 11 EStG): Einnahmen im Jahr des Zuflusses (wirtschaftliche Verfügungsmacht), Ausgaben im Jahr der Leistung; regelmäßig wiederkehrende Einnahmen und Ausgaben, die kurz (bis zehn Tage) vor oder nach dem Jahreswechsel fällig sind und fließen, gehören zum wirtschaftlich zugehörigen Jahr.'],
        schema: ['Einnahme: Geld oder Geldeswert, zugeflossen, im Rahmen der Einkunftsart (§ 8)', 'Sachbezug: üblicher Endpreis (§ 8 Abs. 2)', 'Werbungskosten: Veranlassung (§ 9), sonst Pauschbetrag (§ 9a)', 'Gemischte Aufwendungen: aufteilen, außer untergeordnet oder untrennbar (§ 12 Nr. 1)', 'Zeitpunkt: Zufluss/Abfluss, 10-Tage-Regel (§ 11)'],
        case: { sv: 'Steuerfachangestellte F besucht eine sechstägige Tagung in Lissabon: vier Tage Fachvorträge zum Bilanzsteuerrecht, zwei Tage Stadtführungen. Kosten 2.400 €, gleichmäßig auf die Tage verteilt. Ihre Dezembermiete für eine vermietete Wohnung erhält sie am 4. Januar.',
          steps: [['Wie viel der Tagungskosten sind Werbungskosten?', 'Aufteilung nach Zeitanteilen: 4/6 · 2.400 = 1.600 € Werbungskosten, 800 € nicht abziehbare Lebensführung (§ 12 Nr. 1 EStG).'], ['In welchem Jahr ist die Dezembermiete zu erfassen?', 'Im alten Jahr: regelmäßig wiederkehrende Einnahme, kurz nach Jahresende zugeflossen und zum alten Jahr gehörig (§ 11 Abs. 1 S. 2 EStG), sofern die Fälligkeit ebenfalls in den Zehn-Tage-Zeitraum fällt.']],
          res: '1.600 € Werbungskosten; Dezembermiete im alten Jahr (Zehn-Tage-Regel).' },
        nav: [],
        cards: [['Einnahmen nach § 8 Abs. 1 EStG?', 'Güter in Geld oder Geldeswert, die im Rahmen einer Überschusseinkunftsart zufließen.'], ['Werbungskosten nach § 9 Abs. 1 EStG?', 'Aufwendungen zur Erwerbung, Sicherung und Erhaltung der Einnahmen (Veranlassungsprinzip).'], ['Umgang mit gemischten Aufwendungen?', 'Aufteilung nach objektiven Maßstäben; Ausnahmen bei untergeordneter Mitveranlassung (< 10 %) und untrennbarer Vermischung.'], ['Zehn-Tage-Regel?', 'Regelmäßig wiederkehrende Einnahmen/Ausgaben, die kurz vor oder nach dem Jahreswechsel fällig sind und fließen, gehören zum wirtschaftlich zugehörigen Jahr (§ 11 Abs. 1 S. 2, Abs. 2 S. 2).']] },

      { id: 'e4', t: 'Einkünfte aus nichtselbständiger Arbeit', norms: ['§ 19 EStG', '§ 8 Abs. 2 EStG', '§ 6 Abs. 1 Nr. 4 EStG'], link: 'e3',
        why: 'Dienstwagen, Fortbildung, verbilligte Beteiligung: Arbeitslohn ist mehr als das Gehalt. Die Frage ist immer, ob der Vorteil „für“ die Arbeit gewährt wird.',
        core: ['Zu den Einkünften aus nichtselbständiger Arbeit gehören Gehälter, Löhne und andere Bezüge und Vorteile, die für eine Beschäftigung gewährt werden (§ 19 Abs. 1 S. 1 Nr. 1 EStG), gleich ob laufend oder einmalig und ob ein Rechtsanspruch besteht. Ein Vorteil ist Arbeitslohn, wenn er durch das individuelle Dienstverhältnis veranlasst ist, sich also im weitesten Sinn als Gegenleistung für das Zurverfügungstellen der Arbeitskraft darstellt. Kein Arbeitslohn sind Leistungen im ganz überwiegend eigenbetrieblichen Interesse des Arbeitgebers, etwa eine rein fachliche Fortbildung. Bei gemischten Veranstaltungen wird aufgeteilt: Der private Anteil ist Arbeitslohn. Auch der verbilligte Erwerb einer Beteiligung am Arbeitgeber kann Arbeitslohn sein (Differenz zum gemeinen Wert), wenn er wegen des Dienstverhältnisses gewährt wird.',
          'Die private Nutzung eines Dienstwagens wird nach der Listenpreismethode bewertet (§ 8 Abs. 2 S. 2 i. V. m. § 6 Abs. 1 Nr. 4 S. 2 EStG): monatlich 1 % des inländischen Bruttolistenpreises bei Erstzulassung; dazu für Fahrten zwischen Wohnung und erster Tätigkeitsstätte monatlich 0,03 % des Listenpreises je Entfernungskilometer (§ 8 Abs. 2 S. 3 EStG). Vom Arbeitgeber getragene Kosten wie Benzin sind damit abgegolten. Alternativ: Fahrtenbuch mit den tatsächlichen Kosten. Für Elektro- und Hybridfahrzeuge gelten verminderte Listenpreisansätze. Vom Arbeitnehmer gezahlte Nutzungsentgelte mindern den Vorteil.'],
        schema: ['Vorteil gewährt?', 'Für die Beschäftigung veranlasst? (sonst eigenbetriebliches Interesse)', 'Gemischt: Aufteilen', 'Bewertung: § 8 Abs. 2 (Endpreis) bzw. 1 %-Regel', 'Dienstwagen: 1 % · LP · 12 + 0,03 % · LP · km · 12', 'Abzug: Werbungskosten oder Pauschbetrag 1.230 €'],
        case: { sv: 'Vertriebsleiterin N darf ihren Dienstwagen (Bruttolistenpreis 42.000 €, Verbrenner) ganzjährig privat nutzen. Ihre Wohnung liegt 18 km vom Büro entfernt. Der Arbeitgeber trägt alle Benzinkosten, auch die privaten von 2.100 €. Ein Fahrtenbuch gibt es nicht.',
          steps: [['Vorteil für die Privatnutzung im Jahr?', '1 % · 42.000 · 12 = 5.040 €.'], ['Zuschlag für die Fahrten zur Arbeit?', '0,03 % · 42.000 · 18 · 12 = 2.721,60 €.'], ['Erhöhen die Benzinkosten den Vorteil?', 'Nein, sie sind mit der Listenpreismethode abgegolten. Gesamtvorteil 7.761,60 €.']],
          res: 'Geldwerter Vorteil 7.761,60 € (5.040 + 2.721,60), Benzin abgegolten.' },
        nav: [],
        cards: [['Wann ist ein Vorteil Arbeitslohn?', 'Wenn er durch das individuelle Dienstverhältnis veranlasst ist (Gegenleistung für die Arbeitskraft im weitesten Sinn).'], ['Kein Arbeitslohn trotz Vorteil?', 'Bei ganz überwiegend eigenbetrieblichem Interesse des Arbeitgebers (z. B. fachliche Fortbildung).'], ['1 %-Regel?', 'Monatlich 1 % des Bruttolistenpreises für die Privatnutzung, plus 0,03 % je Entfernungskilometer und Monat für Fahrten zur ersten Tätigkeitsstätte.'], ['Sind vom Arbeitgeber bezahlte Benzinkosten zusätzlicher Arbeitslohn?', 'Nein, mit der Listenpreismethode abgegolten.']] },

      { id: 'e5', t: 'Gewerbebetrieb und seine Abgrenzung', norms: ['§ 15 Abs. 2 EStG', 'Vermögensverwaltung', 'gewerblicher Grundstückshandel'], link: 'e2',
        why: 'Gewerblich oder nicht? Davon hängen Gewerbesteuer, Betriebsvermögen und die Steuerbarkeit von Veräußerungsgewinnen ab. Die Abgrenzung zur Vermögensverwaltung ist Dauerthema.',
        core: ['Gewerbebetrieb ist nach § 15 Abs. 2 EStG eine selbständige, nachhaltige Betätigung, die mit Gewinnerzielungsabsicht unternommen wird und sich als Beteiligung am allgemeinen wirtschaftlichen Verkehr darstellt, wenn sie weder Land- und Forstwirtschaft noch freier Beruf noch andere selbständige Arbeit ist. Als ungeschriebenes Merkmal darf sie den Rahmen privater Vermögensverwaltung nicht überschreiten. Selbständig: auf eigene Rechnung und Gefahr (Unternehmerrisiko und -initiative). Nachhaltig: mit Wiederholungsabsicht. Beteiligung am Verkehr: Leistungen gegen Entgelt am Markt, für Dritte erkennbar.',
          'Vermögensverwaltung liegt vor, wenn Vermögen genutzt wird, indem Substanzwerte erhalten bleiben und Früchte gezogen werden: Vermieten von Wohnungen, Halten von Wertpapieren. Gewerblich wird es erst, wenn die Umschichtung von Substanzwerten in den Vordergrund tritt oder Sonderleistungen hinzukommen. Kurzfristige Vermietung von Wohnungen an Touristen ist noch Vermietung, solange keine hotelähnlichen Zusatzleistungen (Wäsche, Reinigung während des Aufenthalts, Rezeption) und keine hotelähnliche Organisation angeboten werden. Gewerblicher Grundstückshandel: Wer innerhalb von fünf Jahren mehr als drei Objekte anschafft oder bebaut und verkauft, handelt nach der Drei-Objekt-Grenze in der Regel gewerblich. Abgrenzung zur selbständigen Arbeit (§ 18 EStG): Katalogberufe, eigenverantwortliche und leitende Tätigkeit aufgrund eigener Fachkenntnis.'],
        schema: ['Selbständig', 'Nachhaltig', 'Gewinnerzielungsabsicht', 'Beteiligung am allgemeinen wirtschaftlichen Verkehr', 'Keine LuF, kein freier Beruf (§ 18)', 'Keine private Vermögensverwaltung (Substanzumschichtung, Sonderleistungen?)'],
        case: { sv: 'O vermietet zwei Ferienwohnungen über ein Buchungsportal an wechselnde Gäste. Er stellt weder Wäsche noch Reinigung während des Aufenthalts; die Buchung läuft automatisch. Außerdem hat er in vier Jahren fünf Eigentumswohnungen gekauft, saniert und weiterverkauft.',
          steps: [['Sind die Ferienwohnungen ein Gewerbebetrieb?', 'Nein: Ohne hotelähnliche Leistungen und Organisation bleibt es Vermögensverwaltung, Einkünfte aus VuV (§ 21 EStG).'], ['Was ist mit den fünf Wohnungsverkäufen?', 'Gewerblicher Grundstückshandel: mehr als drei Objekte innerhalb von fünf Jahren; die Substanzumschichtung steht im Vordergrund (§ 15 Abs. 2 EStG).'], ['Folge für die Verkaufsgewinne?', 'Laufende gewerbliche Einkünfte, unabhängig von der Haltedauer, und gewerbesteuerpflichtig.']],
          res: 'Ferienwohnungen VuV, Wohnungsverkäufe gewerblicher Grundstückshandel.' },
        nav: [],
        cards: [['Positive Merkmale des Gewerbebetriebs (§ 15 Abs. 2 EStG)?', 'Selbständigkeit, Nachhaltigkeit, Gewinnerzielungsabsicht, Beteiligung am allgemeinen wirtschaftlichen Verkehr.'], ['Ungeschriebenes negatives Merkmal?', 'Keine private Vermögensverwaltung.'], ['Drei-Objekt-Grenze?', 'Mehr als drei Objekte innerhalb von fünf Jahren angeschafft und veräußert: in der Regel gewerblicher Grundstückshandel.'], ['Wann wird Ferienwohnungsvermietung gewerblich?', 'Bei hotelähnlichen Zusatzleistungen und Organisation.']] },

      { id: 'e6', t: 'Gewinnermittlung: Bestandsvergleich und EÜR', norms: ['§ 4 Abs. 1 EStG', '§ 5 EStG', '§ 4 Abs. 3 EStG', '§ 141 AO'], link: 'e5',
        why: 'Gewinneinkünfte werden anders ermittelt als Überschusseinkünfte. Die Klausur fragt, welche Methode gilt und wo die EÜR vom reinen Geldfluss abweicht.',
        core: ['Gewinn nach § 4 Abs. 1 EStG ist der Unterschiedsbetrag zwischen dem Betriebsvermögen am Ende und am Anfang des Wirtschaftsjahres, vermehrt um Entnahmen und vermindert um Einlagen. Gewerbetreibende, die nach Handelsrecht Bücher führen müssen oder es freiwillig tun, ermitteln den Gewinn nach § 5 EStG mit Maßgeblichkeit der Handelsbilanz, soweit keine steuerlichen Wahlrechte oder Vorschriften abweichen. Wer weder nach Handelsrecht noch nach § 141 AO (Umsatz über 800.000 € oder Gewinn über 80.000 €, nach Aufforderung) buchführungspflichtig ist und nicht freiwillig bilanziert, darf den Gewinn durch Einnahmenüberschussrechnung ermitteln (§ 4 Abs. 3 EStG); Freiberufler dürfen das unabhängig von der Größe.',
          'Die EÜR folgt dem Zufluss- und Abflussprinzip (§ 11 EStG), durchbricht es aber dort, wo sonst der Totalgewinn verzerrt würde: Anschaffungskosten für abnutzbares Anlagevermögen werden über die AfA verteilt, für nicht abnutzbares (etwa Grund und Boden) erst bei Veräußerung oder Entnahme abgezogen; Darlehensaufnahme und -tilgung sind keine Betriebseinnahmen und -ausgaben; durchlaufende Posten bleiben außer Ansatz; geringwertige Wirtschaftsgüter dürfen sofort abgezogen werden. Über die Totalperiode führen beide Methoden zum selben Gewinn (Grundsatz der Gesamtgewinngleichheit). Entnahmen und Einlagen werden auch in der EÜR berücksichtigt.'],
        schema: ['Buchführungspflicht? (HGB, § 141 AO) → § 5 bzw. § 4 Abs. 1', 'Sonst Wahl: EÜR (§ 4 Abs. 3)', 'BV-Vergleich: BV Ende − BV Anfang + Entnahmen − Einlagen', 'EÜR: Betriebseinnahmen − Betriebsausgaben nach § 11', 'EÜR-Durchbrechungen: AfA, Grund und Boden, Darlehen, durchlaufende Posten'],
        case: { sv: 'Architekt A ermittelt seinen Gewinn nach § 4 Abs. 3 EStG. Im Jahr erhält er Honorare von 95.000 €, davon 15.000 € erst im Januar des Folgejahres. Er kauft einen Laptop (2.100 €, Nutzungsdauer drei Jahre) im Januar und nimmt ein Bankdarlehen von 20.000 € auf.',
          steps: [['Betriebseinnahmen des Jahres?', '80.000 €: Zufluss entscheidet; die 15.000 € gehören ins Folgejahr. Das Darlehen ist keine Betriebseinnahme.'], ['Abzug für den Laptop?', 'Kein Sofortabzug (über 800 € netto); AfA 2.100 / 3 = 700 € im ersten Jahr (Anschaffung im Januar, volle Monate), sofern keine Sonderregel gewählt wird.'], ['Gewinn ohne weitere Ausgaben?', '80.000 − 700 = 79.300 €.']],
          res: 'Gewinn 79.300 €: Zufluss 80.000 €, Laptop nur über AfA, Darlehen neutral.' },
        nav: [],
        cards: [['Gewinn nach § 4 Abs. 1 EStG?', 'BV am Ende − BV am Anfang + Entnahmen − Einlagen.'], ['Wer darf die EÜR nutzen?', 'Wer nicht nach HGB oder § 141 AO buchführungspflichtig ist und nicht freiwillig bilanziert; Freiberufler stets.'], ['Durchbrechungen des Zuflussprinzips in der EÜR?', 'AfA für abnutzbares AV, nicht abnutzbares AV erst bei Veräußerung/Entnahme, Darlehen neutral, durchlaufende Posten außer Ansatz.'], ['Grundsatz der Gesamtgewinngleichheit?', 'Über die gesamte Lebensdauer des Betriebs ergeben BV-Vergleich und EÜR denselben Totalgewinn.']] },

      { id: 'e7', t: 'Kapitalvermögen und Vermietung', norms: ['§ 20 EStG', '§ 32d EStG', '§ 21 EStG', 'Subsidiarität'], link: 'e3',
        why: 'Zwei Überschusseinkunftsarten mit eigenen Regeln: Abgeltungsteuer und Sparer-Pauschbetrag hier, verbilligte Vermietung und Subsidiarität dort.',
        core: ['Zu den Einkünften aus Kapitalvermögen gehören Dividenden und andere Gewinnausschüttungen (auch verdeckte, § 20 Abs. 1 Nr. 1 S. 2 EStG), Zinsen (Nr. 7) und seit 2009 auch Gewinne aus der Veräußerung von Kapitalanlagen (§ 20 Abs. 2 EStG), unabhängig von der Haltedauer. Sie unterliegen grundsätzlich dem gesonderten Steuertarif von 25 % (Abgeltungsteuer, § 32d Abs. 1 EStG), meist schon durch Kapitalertragsteuer erhoben. Werbungskosten sind nicht abziehbar, es gibt nur den Sparer-Pauschbetrag von 1.000 € (Ehegatten 2.000 €). Ausnahmen vom Abgeltungstarif: Darlehen zwischen nahestehenden Personen und Gesellschafterdarlehen bei Beteiligung ab 10 % (§ 32d Abs. 2 Nr. 1 EStG), Option zum Teileinkünfteverfahren bei Beteiligung ab 25 % oder ab 1 % mit beruflicher Tätigkeit für die Gesellschaft (§ 32d Abs. 2 Nr. 3 EStG). Gehören die Kapitalerträge zu einem Betriebsvermögen, sind sie Gewinneinkünfte (Subsidiarität, § 20 Abs. 8 EStG).',
          'Einkünfte aus Vermietung und Verpachtung (§ 21 EStG) erzielt, wer unbewegliches Vermögen (Grundstücke, Gebäude, Wohnungen) oder Sachinbegriffe zeitlich begrenzt zur Nutzung überlässt. Sie sind subsidiär (§ 21 Abs. 3 EStG): Gehört das Objekt zu einem Betrieb, sind es gewerbliche oder andere Gewinneinkünfte. Bei einer auf Dauer angelegten Wohnungsvermietung wird die Einkünfteerzielungsabsicht typisierend vermutet. Beträgt die Miete für eine Wohnung weniger als 50 % der ortsüblichen Marktmiete, wird die Nutzungsüberlassung in einen entgeltlichen und einen unentgeltlichen Teil aufgeteilt; Werbungskosten sind nur anteilig abziehbar (§ 21 Abs. 2 EStG); ab 66 % gilt die Vermietung als voll entgeltlich, dazwischen entscheidet eine Totalüberschussprognose. Werbungskosten sind etwa Schuldzinsen, Erhaltungsaufwand und die AfA auf das Gebäude (§ 7 Abs. 4 EStG, nicht auf Grund und Boden).'],
        schema: ['Kapital: Ertragsart nach § 20 Abs. 1/2', 'Betriebsvermögen? Dann Gewinneinkünfte (§ 20 Abs. 8)', 'Tarif: 25 % (§ 32d Abs. 1), Ausnahmen § 32d Abs. 2', 'Sparer-Pauschbetrag 1.000 €, keine tatsächlichen WK', 'VuV: Überlassung unbeweglichen Vermögens, Subsidiarität (§ 21 Abs. 3)', 'Miete < 50 % der Marktmiete: Aufteilung (§ 21 Abs. 2)'],
        case: { sv: 'E vermietet eine Wohnung an ihren Sohn für 300 € monatlich; die ortsübliche Miete beträgt 750 €. Die Werbungskosten (Zinsen, AfA, Reparaturen) betragen 6.000 € im Jahr. Außerdem erhält sie 1.400 € Zinsen auf ihrem Tagesgeldkonto.',
          steps: [['Ist die Vermietung voll entgeltlich?', 'Nein: 300 / 750 = 40 %, also unter 50 %. Aufteilung in 40 % entgeltlich, 60 % unentgeltlich (§ 21 Abs. 2 EStG).'], ['Einkünfte aus VuV?', 'Einnahmen 3.600 €, Werbungskosten nur 40 % · 6.000 = 2.400 €; Einkünfte 1.200 €.'], ['Kapitaleinkünfte?', '1.400 − 1.000 Sparer-Pauschbetrag = 400 €, Abgeltungsteuer 25 %.']],
          res: 'VuV 1.200 € (Aufteilung wegen 40 %), Kapital 400 € mit 25 %.' },
        nav: [],
        cards: [['Abgeltungsteuersatz und Pauschbetrag?', '25 % (§ 32d Abs. 1 EStG), Sparer-Pauschbetrag 1.000 € (Ehegatten 2.000 €), keine tatsächlichen Werbungskosten.'], ['Subsidiarität bei § 20 und § 21 EStG?', 'Gehören Kapitalanlage oder Mietobjekt zu einem Betriebsvermögen, sind die Erträge Gewinneinkünfte (§ 20 Abs. 8, § 21 Abs. 3 EStG).'], ['Verbilligte Wohnungsvermietung?', 'Unter 50 % der ortsüblichen Miete: Aufteilung, WK nur anteilig; ab 66 % voll entgeltlich; dazwischen Totalüberschussprognose.'], ['Wann kein Abgeltungstarif bei Zinsen?', 'Bei Darlehen zwischen nahestehenden Personen und bei Gesellschafterdarlehen ab 10 % Beteiligung (§ 32d Abs. 2 Nr. 1 EStG).']] },

      { id: 'e8', t: 'Private Veräußerungen: §§ 17, 22, 23 EStG', norms: ['§ 17 EStG', '§ 22 Nr. 3 EStG', '§ 23 EStG', 'Teileinkünfteverfahren'], link: 'e7',
        why: 'Im Privatvermögen ist die Veräußerung der Quelle grundsätzlich nicht steuerbar. Die Ausnahmen sind präzise abgegrenzt und tauchen in fast jedem Fall auf.',
        core: ['§ 23 EStG erfasst private Veräußerungsgeschäfte: bei Grundstücken, wenn zwischen Anschaffung und Veräußerung nicht mehr als zehn Jahre liegen (ausgenommen Wohnungen, die im Veräußerungsjahr und den zwei Vorjahren oder durchgehend zu eigenen Wohnzwecken genutzt wurden), bei anderen Wirtschaftsgütern bei höchstens einem Jahr; Gegenstände des täglichen Gebrauchs sind ausgenommen. Gewinn ist Veräußerungspreis minus Anschaffungskosten und Werbungskosten (bei vermieteten Gebäuden um die AfA erhöht); er bleibt steuerfrei, wenn alle Gewinne des Jahres unter 1.000 € liegen (Freigrenze seit 2024, vorher 600 €). § 22 Nr. 3 EStG erfasst Entgelte für sonstige Leistungen, die keiner anderen Einkunftsart zugehören (Tun, Dulden, Unterlassen, keine Veräußerung); Freigrenze 256 €. Subsidiarität: § 22 Nr. 3 ist nur zu prüfen, wenn keine andere Einkunftsart greift.',
          '§ 17 EStG: Gewinne aus der Veräußerung von Anteilen an Kapitalgesellschaften im Privatvermögen gehören zu den gewerblichen Einkünften, wenn der Veräußerer innerhalb der letzten fünf Jahre zu mindestens 1 % beteiligt war; § 17 geht § 20 Abs. 2 EStG vor. Veräußerungsgewinn = Veräußerungspreis − Veräußerungskosten − Anschaffungskosten. Im Teileinkünfteverfahren sind 60 % steuerpflichtig (§ 3 Nr. 40 Buchst. c EStG), Kosten zu 60 % abziehbar (§ 3c Abs. 2 EStG). Freibetrag (§ 17 Abs. 3 EStG): 9.060 € anteilig nach der Beteiligungsquote, gekürzt um den Betrag, um den der Gewinn den anteiligen Betrag von 36.100 € übersteigt; die Beträge werden auf den steuerpflichtigen Teil angewandt.'],
        schema: ['Kapitalgesellschaftsanteil ≥ 1 % in 5 Jahren? → § 17 (Teileinkünfte 60 %)', 'Sonst Wertpapiere: § 20 Abs. 2 (25 %)', 'Grundstück ≤ 10 Jahre, anderes WG ≤ 1 Jahr: § 23 (Freigrenze 1.000 €)', 'Leistung (Tun, Dulden, Unterlassen) gegen Entgelt: § 22 Nr. 3 (Freigrenze 256 €)', 'Sonst nicht steuerbar'],
        case: { sv: 'Q verkauft ihre 20 %-Beteiligung an einer GmbH (Anschaffungskosten 30.000 €) für 80.000 €, Notarkosten 1.000 €. Außerdem verkauft sie eine Briefmarkensammlung, die sie seit fünf Jahren besitzt, mit 4.000 € Gewinn.',
          steps: [['Veräußerungsgewinn nach § 17 und steuerpflichtiger Teil?', '80.000 − 1.000 − 30.000 = 49.000 €; davon 60 % = 29.400 €.'], ['Freibetrag?', 'Anteilig 20 % · 9.060 = 1.812 €; Kürzungsgrenze 20 % · 36.100 = 7.220 €. Der stpfl. Teil 29.400 € übersteigt sie um 22.180 €, der Freibetrag entfällt. Steuerpflichtig 29.400 €.'], ['Briefmarken?', 'Haltedauer über ein Jahr: kein privates Veräußerungsgeschäft, nicht steuerbar.']],
          res: '§ 17: 29.400 € steuerpflichtig, kein Freibetrag; Briefmarken nicht steuerbar.' },
        nav: [],
        cards: [['Fristen des § 23 EStG?', 'Grundstücke zehn Jahre (Ausnahme eigene Wohnzwecke), andere Wirtschaftsgüter ein Jahr, Gegenstände des täglichen Gebrauchs ausgenommen.'], ['Freigrenze bei § 23 EStG?', 'Gewinne unter 1.000 € im Jahr bleiben steuerfrei (ab 2024; zuvor 600 €).'], ['Voraussetzung des § 17 EStG?', 'Beteiligung von mindestens 1 % innerhalb der letzten fünf Jahre an einer Kapitalgesellschaft im Privatvermögen.'], ['Freibetrag nach § 17 Abs. 3 EStG?', '9.060 € anteilig, gekürzt um den Betrag, um den der Gewinn anteilig 36.100 € übersteigt.']] },

      { id: 'e9', t: 'Sonderausgaben und außergewöhnliche Belastungen', norms: ['§ 10 EStG', '§ 10b EStG', '§ 33 EStG', 'zumutbare Belastung'], link: 'e2',
        why: 'Vom Gesamtbetrag der Einkünfte zum Einkommen: Hier wird das subjektive Nettoprinzip umgesetzt. Die Klausur prüft vor allem § 33 EStG mit seinen drei Merkmalen.',
        core: ['Sonderausgaben sind privat veranlasste Aufwendungen, die der Gesetzgeber ausnahmsweise zum Abzug zulässt, abschließend aufgezählt: Vorsorgeaufwendungen (Kranken-, Pflege-, Rentenversicherung), Kirchensteuer, Kinderbetreuungskosten, Schulgeld, Spenden (§ 10b EStG, bis 20 % des GdE), Unterhalt an den geschiedenen Ehegatten im Realsplitting. Ohne Nachweis gilt ein Pauschbetrag von 36 € (§ 10c EStG) für bestimmte Sonderausgaben. Abgezogen wird vom Gesamtbetrag der Einkünfte.',
          'Außergewöhnliche Belastungen (§ 33 EStG) sind Aufwendungen, die einem Steuerpflichtigen zwangsläufig größer erwachsen als der überwiegenden Mehrzahl vergleichbarer Steuerpflichtiger. Drei Merkmale: Belastung (endgültiger Vermögensabfluss ohne Gegenwert), Außergewöhnlichkeit (nicht übliche Kosten der Lebensführung), Zwangsläufigkeit (aus rechtlichen, tatsächlichen oder sittlichen Gründen, nicht vermeidbar). Typisch sind Krankheitskosten und behinderungsbedingte Umbaukosten; wie die Krankheit oder der Unfall verursacht wurde (etwa im Urlaub), ist für die Zwangsläufigkeit der Aufwendungen regelmäßig unerheblich. Abziehbar ist nur der Teil, der die zumutbare Belastung (§ 33 Abs. 3 EStG, gestaffelt nach GdE, Familienstand und Kinderzahl) übersteigt. Für typische Fälle gibt es Pauschbeträge, etwa für Menschen mit Behinderungen (§ 33b EStG).'],
        schema: ['GdE', '− Sonderausgaben (abschließender Katalog, sonst 36 € Pauschbetrag)', '− agB: Belastung, außergewöhnlich, zwangsläufig (§ 33)', '− davon zumutbare Belastung (§ 33 Abs. 3)', '= Einkommen'],
        case: { sv: 'Nach einem Skiunfall ist Y dauerhaft gehbehindert. Sie lässt ihr Bad für 9.000 € barrierefrei umbauen; die Krankenkasse zahlt nichts. Ihre zumutbare Belastung beträgt 2.600 €. Ihr Finanzamt meint, wer Ski fährt, trage das Risiko selbst.',
          steps: [['Belastung und Außergewöhnlichkeit?', 'Ja: endgültiger Abfluss ohne Gegenwert im Sinne eines marktgängigen Vermögenszuwachses; behinderungsbedingter Umbau ist nicht üblich.'], ['Zwangsläufig, obwohl der Unfall bei einem Hobby geschah?', 'Ja: Die Aufwendungen sind wegen der Behinderung tatsächlich unausweichlich; die Ursache der Behinderung ist unerheblich.'], ['Abzugsbetrag?', '9.000 − 2.600 = 6.400 € außergewöhnliche Belastung.']],
          res: 'Umbaukosten sind agB; abziehbar 6.400 €.' },
        nav: [],
        cards: [['Was sind Sonderausgaben?', 'Abschließend aufgezählte private Aufwendungen, die vom GdE abgezogen werden (Vorsorge, Kirchensteuer, Spenden u. a.).'], ['Drei Merkmale der außergewöhnlichen Belastung?', 'Belastung, Außergewöhnlichkeit, Zwangsläufigkeit.'], ['Wovon hängt die zumutbare Belastung ab?', 'Vom Gesamtbetrag der Einkünfte, Familienstand und Zahl der Kinder (§ 33 Abs. 3 EStG).'], ['Sonderausgaben-Pauschbetrag?', '36 € (Ehegatten 72 €), § 10c EStG.']] },
    ],
    unt: [
      { id: 'u1', t: 'Rechtsform und Einzelunternehmer', norms: ['Transparenz', 'Trennungsprinzip', '§ 15 Abs. 1 Nr. 1 EStG', 'Betrieb'], link: 'e5',
        why: 'Ob Einzelunternehmen, Personen- oder Kapitalgesellschaft: Die Rechtsform entscheidet, wer Steuersubjekt ist. Das ist die Landkarte des Unternehmenssteuerrechts.',
        core: ['Unternehmenssteuerrecht ist der Oberbegriff für die Besteuerung unternehmerischer Betätigung. Natürliche Personen als Einzelunternehmer und Personengesellschaften werden transparent besteuert: Der Gewinn wird dem Unternehmer bzw. den Gesellschaftern zugerechnet und unterliegt bei ihnen der Einkommensteuer (Personengesellschaften sind selbst nicht einkommensteuerpflichtig, aber Subjekt der Gewinnermittlung und der Gewerbesteuer). Kapitalgesellschaften sind eigene Steuersubjekte der Körperschaftsteuer (Trennungsprinzip); die Gesellschafter versteuern erst die Ausschüttungen. Seit 2022 können Personenhandelsgesellschaften zur Körperschaftsteuer optieren (§ 1a KStG). Die Rechtsformwahl ist daher ein Gestaltungsansatz.',
          'Einzelunternehmer erzielen Einkünfte aus Gewerbebetrieb nach § 15 Abs. 1 S. 1 Nr. 1 EStG. Zu trennen sind der Betrieb und die Privatsphäre des Unternehmers: Wirtschaftsgüter gehören zum notwendigen Betriebsvermögen (ausschließlich und unmittelbar betrieblich genutzt, bei Grundstücken anteilig), zum notwendigen Privatvermögen oder, bei Bilanzierenden, zum gewillkürten Betriebsvermögen (betriebliche Nutzung zwischen 10 und 50 %). Ein Unternehmer kann mehrere Betriebe haben; ob mehrere Betriebe oder einer, entscheidet sich nach dem wirtschaftlichen, finanziellen und organisatorischen Zusammenhang (gleichartige Tätigkeiten sprechen für einen Betrieb). Das hat etwa Bedeutung für den Gewerbesteuer-Freibetrag und die Betriebsveräußerung.'],
        schema: ['Rechtsform bestimmen: EU, PersG, KapG', 'Transparenz (EU, PersG) vs. Trennung (KapG)', 'EU: § 15 Abs. 1 Nr. 1 EStG', 'Betriebs- oder Privatvermögen? (notwendig, gewillkürt)', 'Ein oder mehrere Betriebe? (Zusammenhang)'],
        case: { sv: 'Malermeisterin K führt einen Malerbetrieb und betreibt in einer anderen Stadt einen Online-Shop für Modellbau mit eigenem Personal, eigener Buchhaltung und eigenen Kunden. Ihr Pkw wird zu 70 % betrieblich genutzt.',
          steps: [['Ein Betrieb oder zwei?', 'Zwei: ungleichartige Tätigkeiten ohne wirtschaftlichen, finanziellen und organisatorischen Zusammenhang.'], ['Zu welchem Vermögen gehört der Pkw?', 'Notwendiges Betriebsvermögen (betriebliche Nutzung über 50 %); die Privatnutzung ist eine Entnahme.'], ['Wer zahlt die Einkommensteuer auf die Gewinne?', 'K selbst, Transparenz beim Einzelunternehmer (§ 15 Abs. 1 Nr. 1 EStG).']],
          res: 'Zwei Gewerbebetriebe, Pkw notwendiges BV, ESt bei K.' },
        nav: [],
        cards: [['Transparenz- vs. Trennungsprinzip?', 'Transparenz: Gewinn wird den Inhabern/Gesellschaftern zugerechnet (EU, PersG). Trennung: KapG ist eigenes Steuersubjekt, Gesellschafter versteuern Ausschüttungen.'], ['Notwendiges Betriebsvermögen?', 'Wirtschaftsgüter, die ausschließlich und unmittelbar betrieblich genutzt werden (bei beweglichen WG über 50 %).'], ['Gewillkürtes Betriebsvermögen?', 'Bei Bilanzierenden: Wirtschaftsgüter mit 10 bis 50 % betrieblicher Nutzung, die dem Betrieb gewidmet werden.'], ['Seit wann können PersG zur KSt optieren?', 'Seit 2022 (§ 1a KStG).']] },

      { id: 'u2', t: 'Mitunternehmerschaft: Tatbestand und Gewinnverteilung', norms: ['§ 15 Abs. 1 Nr. 2 EStG', 'Mitunternehmerrisiko', 'Mitunternehmerinitiative', 'Familiengesellschaft'], link: 'u1',
        why: 'Wer ist Mitunternehmer, und wie viel vom Gewinn gehört ihm steuerlich? Bei Familiengesellschaften schaut das Finanzamt besonders genau hin.',
        core: ['Gesellschafter einer OHG, KG oder anderen Gesellschaft, die als Unternehmer (Mitunternehmer) anzusehen sind, beziehen gewerbliche Einkünfte (§ 15 Abs. 1 S. 1 Nr. 2 EStG). Mitunternehmer ist, wer Mitunternehmerrisiko trägt (Beteiligung an Gewinn und Verlust und an den stillen Reserven einschließlich Geschäftswert) und Mitunternehmerinitiative entfalten kann (Teilhabe an unternehmerischen Entscheidungen, mindestens Stimm-, Kontroll- und Widerspruchsrechte wie ein Kommanditist nach dem HGB). Beide Merkmale müssen vorliegen, können sich aber gegenseitig ausgleichen. Die Personengesellschaft ist teilrechtsfähig: Sie ist Subjekt der Gewinnermittlung, der Gewinn wird aber den Gesellschaftern zugerechnet und dort versteuert.',
          'Der Gewinn wird nach dem gesellschaftsvertraglichen Schlüssel verteilt, sonst nach HGB. Bei Familienpersonengesellschaften prüft die Rechtsprechung, ob der Gesellschaftsvertrag ernsthaft gewollt, zivilrechtlich wirksam und tatsächlich durchgeführt ist und einem Fremdvergleich standhält: Minderjährige Kinder müssen etwa wirksam vertreten sein (Ergänzungspfleger), und ihre Rechte dürfen nicht hinter denen eines fremden Kommanditisten zurückbleiben. Ist die Gewinnverteilung unangemessen hoch zugunsten unentgeltlich beteiligter Angehöriger, wird sie korrigiert; die Rechtsprechung hält eine Rendite von bis zu 15 % des tatsächlichen Werts der geschenkten Beteiligung für angemessen. Der Mehrbetrag wird den Eltern zugerechnet. Eine Entnahme durch einen Gesellschafter (auch eine verdeckte, etwa zu günstige Lieferungen an ihn) mindert den Gewinn nicht.'],
        schema: ['Gesellschaft mit gewerblicher Tätigkeit?', 'Mitunternehmerrisiko (Gewinn, Verlust, stille Reserven)', 'Mitunternehmerinitiative (mind. Kommanditistenrechte)', 'Gewinnverteilung nach Vertrag', 'Familien-PersG: wirksam, durchgeführt, Fremdvergleich, Angemessenheit (15 %)'],
        case: { sv: 'Vater V überträgt seinen beiden volljährigen Kindern schenkweise je eine Kommanditbeteiligung an seiner KG (tatsächlicher Wert je 100.000 €). Laut Vertrag erhalten sie je 30 % des Gewinns; der Gewinn beträgt 200.000 €. Die Kinder haben die gesetzlichen Kommanditistenrechte.',
          steps: [['Sind die Kinder Mitunternehmer?', 'Ja: Beteiligung an Gewinn, Verlust und stillen Reserven, Kommanditistenrechte genügen für die Initiative.'], ['Angemessener Gewinnanteil je Kind?', 'Höchstens 15 % von 100.000 € = 15.000 €.'], ['Steuerliche Zurechnung?', 'Je Kind 15.000 €; der Rest der vertraglichen 60.000 € (je 45.000 €) wird V zugerechnet.']],
          res: 'Kinder Mitunternehmer mit je 15.000 €, Mehrbetrag 90.000 € bei V.' },
        nav: [],
        cards: [['Mitunternehmerrisiko?', 'Teilhabe am Erfolg und Misserfolg: Gewinn, Verlust, stille Reserven einschließlich Geschäftswert.'], ['Mitunternehmerinitiative?', 'Teilhabe an unternehmerischen Entscheidungen, mindestens die Rechte eines Kommanditisten nach HGB.'], ['Prüfung einer Familienpersonengesellschaft?', 'Zivilrechtlich wirksam, ernsthaft gewollt, tatsächlich durchgeführt, fremdüblich, angemessene Gewinnverteilung.'], ['Angemessene Rendite bei geschenkter Beteiligung?', 'Bis zu 15 % des tatsächlichen Werts der Beteiligung (Rechtsprechung).']] },

      { id: 'u3', t: 'Sondervergütungen, Sonderbetriebsvermögen, Feststellung', norms: ['§ 15 Abs. 1 S. 1 Nr. 2 Hs. 2 EStG', 'SBV I/II', '§ 180 AO'], link: 'u2',
        why: 'Der Gesellschafter, der seiner KG Geld leiht oder für sie arbeitet, bekommt dafür keine Zinsen oder Gehalt im steuerlichen Sinn, sondern gewerbliche Einkünfte. Diese Umqualifizierung ist ein Prüfungsschwerpunkt.',
        core: ['Vergütungen, die ein Mitunternehmer von der Gesellschaft für seine Tätigkeit, für die Hingabe von Darlehen oder für die Überlassung von Wirtschaftsgütern bezieht, gehören zu seinen gewerblichen Einkünften (§ 15 Abs. 1 S. 1 Nr. 2 Hs. 2 EStG). Sie mindern zwar den Gewinn der Gesellschaft (Gesamthandsbilanz), werden aber dem Gesellschafter im Sonderbereich wieder hinzugerechnet. Ziel ist die Gleichstellung mit dem Einzelunternehmer, der sich selbst kein Gehalt zahlen kann. Gleiches gilt für einen Rechtsanwalt, der als Kommanditist seine KG berät: Sein Honorar ist Sondervergütung, nicht Einkunft aus § 18 EStG.',
          'Sonderbetriebsvermögen sind Wirtschaftsgüter im Eigentum eines Mitunternehmers, die der Gesellschaft dienen (SBV I, etwa ein an die KG vermietetes Grundstück) oder seiner Beteiligung (SBV II, etwa ein Darlehen zur Finanzierung der Einlage oder die Beteiligung an der Komplementär-GmbH). Damit zusammenhängende Aufwendungen sind Sonderbetriebsausgaben, Erträge Sonderbetriebseinnahmen. Der steuerliche Gesamtgewinn einer Mitunternehmerschaft wird zweistufig ermittelt: Stufe 1 Gewinn laut Gesamthandsbilanz (ggf. mit Ergänzungsbilanzen), Stufe 2 Sonderbilanzen und Sondervergütungen. Er wird gesondert und einheitlich festgestellt (§§ 179, 180 Abs. 1 S. 1 Nr. 2 Buchst. a AO); dieser Feststellungsbescheid ist Grundlagenbescheid für die ESt-Bescheide der Gesellschafter.'],
        schema: ['Stufe 1: Gewinnanteil aus der Gesamthandsbilanz', 'Stufe 2: Sondervergütungen (Tätigkeit, Darlehen, Überlassung)', '+ Sonderbetriebseinnahmen − Sonderbetriebsausgaben', 'SBV I (dient der Gesellschaft), SBV II (dient der Beteiligung)', 'Gesonderte und einheitliche Feststellung (§ 180 AO)'],
        case: { sv: 'Kommanditist R ist zu 40 % an der S-KG beteiligt. Die KG hat nach Abzug aller Aufwendungen einen Gewinn von 100.000 €; darin sind als Aufwand enthalten: 60.000 € Geschäftsführergehalt an R, 12.000 € Miete an R für eine Lagerhalle und 3.000 € Zinsen an R. R zahlt für die Halle 4.000 € Grundsteuer und Reparaturen.',
          steps: [['Gewinnanteil aus der Gesamthand?', '40 % · 100.000 = 40.000 €.'], ['Sondervergütungen?', '60.000 + 12.000 + 3.000 = 75.000 €.'], ['Einkünfte des R aus § 15?', '40.000 + 75.000 − 4.000 Sonderbetriebsausgaben = 111.000 €; die Halle ist SBV I.']],
          res: 'R erzielt 111.000 € gewerbliche Einkünfte, die Halle ist Sonderbetriebsvermögen I.' },
        nav: [],
        cards: [['Welche Vergütungen erfasst § 15 Abs. 1 S. 1 Nr. 2 Hs. 2 EStG?', 'Für Tätigkeit im Dienst der Gesellschaft, für Darlehen und für die Überlassung von Wirtschaftsgütern.'], ['SBV I vs. SBV II?', 'SBV I dient unmittelbar dem Betrieb der Gesellschaft, SBV II der Beteiligung des Gesellschafters.'], ['Zwei Stufen der Gewinnermittlung bei der Mitunternehmerschaft?', 'Gesamthandsbilanz (mit Ergänzungsbilanzen), dann Sonderbereich (Sonderbilanzen, Sondervergütungen).'], ['Wie wird der Gewinn einer Mitunternehmerschaft verfahrensrechtlich festgestellt?', 'Gesondert und einheitlich (§ 180 Abs. 1 S. 1 Nr. 2 Buchst. a AO); Grundlagenbescheid für die ESt der Gesellschafter.']] },

      { id: 'u4', t: 'Vermögensverwaltende PersG, Abfärbung und Prägung', norms: ['§ 15 Abs. 3 EStG', '§ 39 Abs. 2 Nr. 2 AO', 'GmbH & Co. KG'], link: 'u3',
        why: 'Eine KG ist nicht automatisch gewerblich. Ob sie es wird, hängt an Abfärbung und Prägung, und das schwere Klausurbeispiel des Moduls dreht sich genau darum.',
        core: ['Eine Personengesellschaft, die nur Vermögen verwaltet (etwa Grundstücke vermietet oder Beteiligungen hält), erzielt keine gewerblichen Einkünfte, sondern Überschusseinkünfte (§ 20, § 21 EStG), die den Gesellschaftern anteilig zugerechnet werden (§ 39 Abs. 2 Nr. 2 AO, Bruchteilsbetrachtung). Ausnahmen in § 15 Abs. 3 EStG: Nr. 1 (Abfärbung): Übt die Gesellschaft auch eine gewerbliche Tätigkeit aus oder bezieht sie gewerbliche Einkünfte aus einer Beteiligung an einer anderen Mitunternehmerschaft, gilt ihre gesamte Tätigkeit als Gewerbebetrieb. Für eigene Tätigkeit gibt es eine Bagatellgrenze (gewerbliche Umsätze bis 3 % der Gesamtumsätze und höchstens 24.500 € im Jahr färben nicht ab).',
          'Nr. 2 (gewerbliche Prägung): Eine Personengesellschaft ohne gewerbliche Tätigkeit gilt in vollem Umfang als Gewerbebetrieb, wenn ausschließlich eine oder mehrere Kapitalgesellschaften persönlich haftende Gesellschafter sind und nur diese oder Nichtgesellschafter zur Geschäftsführung befugt sind, typischerweise die GmbH & Co. KG. Folge der Gewerblichkeit: Betriebsvermögen, Veräußerungsgewinne steuerbar, Gewerbesteuerpflicht. Liegt kein Gewerbe vor, werden die Einkünfte gleichwohl gesondert und einheitlich festgestellt (§ 180 Abs. 1 S. 1 Nr. 2 Buchst. a AO), weil mehrere Personen beteiligt sind. Hält ein Gesellschafter seinen Anteil an einer vermögensverwaltenden Gesellschaft im Betriebsvermögen, werden die Einkünfte auf seiner Ebene in gewerbliche umqualifiziert (Zebragesellschaft).'],
        schema: ['Eigene gewerbliche Tätigkeit? (§ 15 Abs. 2)', 'Sonst Abfärbung: gewerbliche Nebentätigkeit (Bagatellgrenze) oder Beteiligungseinkünfte (§ 15 Abs. 3 Nr. 1)', 'Sonst Prägung: nur KapG haftet und führt Geschäfte (§ 15 Abs. 3 Nr. 2)', 'Sonst vermögensverwaltend: § 20/§ 21, Zurechnung § 39 Abs. 2 Nr. 2 AO', 'Feststellung (§ 180 AO) in jedem Fall'],
        case: { sv: 'Die W-KG (Komplementär: eine natürliche Person, die die Geschäfte führt) vermietet ein Bürohaus. Sie hält außerdem 2 % als Kommanditistin an einer GmbH & Co. KG, bei der nur die GmbH haftet und Geschäfte führt und die ebenfalls nur vermietet.',
          steps: [['Ist die GmbH & Co. KG gewerblich?', 'Ja, gewerblich geprägt (§ 15 Abs. 3 Nr. 2 EStG): nur eine KapG haftet und führt die Geschäfte.'], ['Färbt das auf die W-KG ab?', 'Ja: Sie bezieht gewerbliche Einkünfte aus einer Beteiligung an einer Mitunternehmerschaft (§ 15 Abs. 3 Nr. 1 Alt. 2 EStG); ihre gesamte Tätigkeit gilt einkommensteuerlich als Gewerbebetrieb.'], ['Und die Mieten der W-KG?', 'Sie werden damit zu gewerblichen Einkünften; ohne die Beteiligung wären es Einkünfte aus VuV.']],
          res: 'Prägung der GmbH & Co. KG, Abfärbung über Beteiligungseinkünfte auf die W-KG.' },
        nav: [],
        cards: [['Was bewirkt die Abfärbung nach § 15 Abs. 3 Nr. 1 EStG?', 'Eine gewerbliche Teiltätigkeit oder gewerbliche Beteiligungseinkünfte machen die gesamte Tätigkeit der PersG gewerblich.'], ['Bagatellgrenze bei der Abfärbung?', 'Gewerbliche Umsätze bis 3 % der Gesamtumsätze und höchstens 24.500 € im Jahr.'], ['Voraussetzungen der gewerblichen Prägung?', 'Ausschließlich Kapitalgesellschaften sind persönlich haftend, und nur diese oder Nichtgesellschafter führen die Geschäfte.'], ['Zurechnung bei vermögensverwaltender PersG?', 'Anteilig bei den Gesellschaftern nach § 39 Abs. 2 Nr. 2 AO (Bruchteilsbetrachtung).']] },

      { id: 'u5', t: 'Betriebsveräußerung und Betriebsaufgabe', norms: ['§ 16 EStG', '§ 34 EStG', 'Freibetrag 45.000 €'], link: 'u3',
        why: 'Beim Verkauf des ganzen Betriebs werden die stillen Reserven auf einen Schlag versteuert. § 16 EStG regelt, was dazugehört und welche Vergünstigungen es gibt.',
        core: ['Zu den gewerblichen Einkünften gehören auch Gewinne aus der Veräußerung des ganzen Gewerbebetriebs, eines Teilbetriebs (organisatorisch geschlossener, mit gewisser Selbständigkeit ausgestatteter Teil, der für sich lebensfähig ist), eines Mitunternehmeranteils oder des Anteils eines persönlich haftenden Gesellschafters einer KGaA (§ 16 Abs. 1 EStG). Der Betriebsaufgabe steht die Veräußerung gleich (§ 16 Abs. 3 EStG): Die wesentlichen Betriebsgrundlagen werden in einem einheitlichen Vorgang an verschiedene Erwerber veräußert oder ins Privatvermögen überführt; anzusetzen ist dann der gemeine Wert. Veräußerungsgewinn = Veräußerungspreis − Veräußerungskosten − Wert des Betriebsvermögens (Buchwert).',
          'Vergünstigungen: Ein Freibetrag von 45.000 €, wenn der Steuerpflichtige das 55. Lebensjahr vollendet hat oder dauernd berufsunfähig ist, auf Antrag und nur einmal im Leben; er ermäßigt sich um den Betrag, um den der Gewinn 136.000 € übersteigt (§ 16 Abs. 4 EStG). Außerdem Tarifermäßigung nach § 34 EStG (Fünftelregelung oder, einmal im Leben ab 55, ermäßigter Steuersatz von 56 % des durchschnittlichen Steuersatzes). Soweit auf Veräußerer- und Erwerberseite dieselben Personen Unternehmer sind, gilt der Gewinn als laufender Gewinn (§ 16 Abs. 2 S. 3 EStG). Der Erwerber aktiviert die gezahlten Anschaffungskosten auf die erworbenen Wirtschaftsgüter einschließlich eines Geschäftswerts; beim Erwerb eines Mitunternehmeranteils über Buchwert geschieht das in einer Ergänzungsbilanz.'],
        schema: ['Veräußerungsobjekt: Betrieb, Teilbetrieb, Mitunternehmeranteil (§ 16 Abs. 1)', 'Oder Aufgabe: wesentliche Betriebsgrundlagen, gemeiner Wert (§ 16 Abs. 3)', 'Gewinn = Preis − Kosten − Buchwert', 'Freibetrag 45.000 € (55 J./berufsunfähig), Abschmelzung über 136.000 €', 'Tarif: § 34 EStG'],
        case: { sv: 'Bäckermeister B (58 Jahre) verkauft seinen Betrieb für 300.000 €. Buchwert des Betriebsvermögens 110.000 €, Veräußerungskosten 6.000 €. Er hat den Freibetrag noch nie genutzt.',
          steps: [['Veräußerungsgewinn?', '300.000 − 6.000 − 110.000 = 184.000 €.'], ['Freibetrag nach § 16 Abs. 4 EStG?', 'Der Gewinn übersteigt 136.000 € um 48.000 €; der Freibetrag von 45.000 € ist damit vollständig abgeschmolzen: 0 €.'], ['Was bleibt an Begünstigung?', 'Tarifermäßigung nach § 34 EStG (Fünftelregelung oder auf Antrag der ermäßigte Satz ab 55).']],
          res: 'Veräußerungsgewinn 184.000 €, Freibetrag 0 €, § 34 EStG anwendbar.' },
        nav: [],
        cards: [['Was erfasst § 16 Abs. 1 EStG?', 'Veräußerung des ganzen Gewerbebetriebs, eines Teilbetriebs, eines Mitunternehmeranteils, eines KGaA-Komplementäranteils.'], ['Veräußerungsgewinn nach § 16 Abs. 2 EStG?', 'Veräußerungspreis − Veräußerungskosten − Wert des Betriebsvermögens.'], ['Freibetrag nach § 16 Abs. 4 EStG?', '45.000 € ab 55 Jahren oder bei dauernder Berufsunfähigkeit, einmal im Leben, gekürzt um den Betrag über 136.000 €.'], ['Bewertung bei Betriebsaufgabe?', 'Gemeiner Wert der ins Privatvermögen überführten Wirtschaftsgüter, Veräußerungspreis für die verkauften.']] },

      { id: 'u6', t: 'Körperschaftsteuer: Subjekt und Einkommen', norms: ['§ 1 KStG', '§ 8 KStG', '§ 10 KStG', '§ 23 KStG'], link: 'u1',
        why: 'Die Kapitalgesellschaft hat keine Privatsphäre. Daraus folgen die Besonderheiten bei Einkunftsart, Liebhaberei und nichtabziehbaren Aufwendungen.',
        core: ['Unbeschränkt körperschaftsteuerpflichtig sind Körperschaften mit Geschäftsleitung oder Sitz im Inland (§ 1 Abs. 1 KStG), vor allem Kapitalgesellschaften (GmbH, AG, SE), Genossenschaften, Vereine und Stiftungen. Beschränkt steuerpflichtig sind ausländische Körperschaften mit inländischen Einkünften (§ 2 KStG). Ob ein ausländisches Gebilde Körperschaftsteuersubjekt ist, entscheidet ein Typenvergleich mit deutschen Rechtsformen. Das Einkommen wird nach den Vorschriften des EStG ermittelt (§ 8 Abs. 1 KStG); bei Kapitalgesellschaften, die zur Buchführung verpflichtet sind, sind alle Einkünfte gewerblich (§ 8 Abs. 2 KStG). Es gibt keine Privatsphäre und deshalb auch keine Liebhaberei; Verluste sind grundsätzlich voll zu berücksichtigen.',
          'Nichtabziehbar sind unter anderem die Körperschaftsteuer selbst und andere Personensteuern, Geldstrafen und die Hälfte der Aufsichtsratsvergütungen (§ 10 KStG), außerdem die Gewerbesteuer (§ 4 Abs. 5b EStG). Spenden sind in Grenzen nach § 9 Abs. 1 Nr. 2 KStG abziehbar. Verluste werden nach § 10d EStG vor- und rückgetragen (§ 8 Abs. 1 KStG); bei einem schädlichen Beteiligungserwerb von mehr als 50 % gehen sie unter (§ 8c KStG), mit Ausnahmen. Steuersatz 15 % (§ 23 Abs. 1 KStG), dazu Solidaritätszuschlag 5,5 % der KSt; ab 2028 sinkt der Satz schrittweise um einen Punkt pro Jahr bis auf 10 % im Jahr 2032. Veranlagt wird nach Ablauf des Kalenderjahres; Gewinnausschüttungen unterliegen der Kapitalertragsteuer, die die Gesellschaft für den Gesellschafter einbehält.'],
        schema: ['Steuersubjekt: § 1 (unbeschränkt) / § 2 (beschränkt), ggf. Typenvergleich', 'Einkommen nach EStG (§ 8 Abs. 1), alles gewerblich (§ 8 Abs. 2)', 'Keine Privatsphäre, keine Liebhaberei', '+ nichtabziehbare Aufwendungen (§ 10 KStG, § 4 Abs. 5b EStG)', '− Spenden (§ 9), − Verlustabzug (§ 10d, § 8c)', '· 15 % KSt + 5,5 % Soli'],
        case: { sv: 'Die T-GmbH weist einen Jahresüberschuss von 300.000 € aus. Darin als Aufwand gebucht: Körperschaftsteuer-Vorauszahlungen 40.000 €, Gewerbesteuer 45.000 €, eine Geldbuße 5.000 €, Aufsichtsratsvergütung 20.000 €.',
          steps: [['Welche Aufwendungen werden hinzugerechnet?', 'KSt 40.000 (§ 10 Nr. 2), GewSt 45.000 (§ 4 Abs. 5b EStG), Geldbuße 5.000 (§ 4 Abs. 5 Nr. 8 EStG), die Hälfte der Aufsichtsratsvergütung 10.000 (§ 10 Nr. 4 KStG).'], ['Zu versteuerndes Einkommen?', '300.000 + 40.000 + 45.000 + 5.000 + 10.000 = 400.000 €.'], ['Körperschaftsteuer und Soli?', '15 % · 400.000 = 60.000 €; Soli 5,5 % = 3.300 €.']],
          res: 'Einkommen 400.000 €, KSt 60.000 €, Soli 3.300 €.' },
        nav: [],
        cards: [['Wann ist eine Körperschaft unbeschränkt steuerpflichtig?', 'Bei Sitz oder Geschäftsleitung im Inland (§ 1 Abs. 1 KStG).'], ['Welche Einkunftsart hat eine GmbH?', 'Nur gewerbliche Einkünfte (§ 8 Abs. 2 KStG).'], ['Nichtabziehbare Aufwendungen nach § 10 KStG (Auswahl)?', 'Körperschaftsteuer und Personensteuern, Geldstrafen, die Hälfte der Aufsichtsratsvergütungen.'], ['KSt-Satz und Soli?', '15 % (bis 2027; ab 2028 schrittweise bis 10 % 2032) plus 5,5 % Soli auf die KSt.']] },

      { id: 'u7', t: 'Trennungsprinzip, Anteilseigner, vGA und verdeckte Einlage', norms: ['§ 8 Abs. 3 KStG', '§ 8b KStG', '§ 20 Abs. 1 Nr. 1 EStG', '§ 3 Nr. 40 EStG'], link: 'u6',
        why: 'Gesellschaft und Gesellschafter sind getrennte Welten. Was zwischen ihnen fließt, muss fremdüblich sein, sonst korrigiert die vGA. Das ist der Kern der Körperschaftsteuerklausur.',
        core: ['Trennungsprinzip: Die Kapitalgesellschaft versteuert ihr Einkommen selbst, der Gesellschafter seine Ausschüttungen. Verträge zwischen beiden (Gehalt, Miete, Darlehen) werden steuerlich anerkannt, wenn sie fremdüblich sind. Besteuerung der Anteilseigner: Natürliche Person mit Anteil im Privatvermögen: Kapitaleinkünfte (§ 20 Abs. 1 Nr. 1 EStG) mit 25 % Abgeltungsteuer. Anteil im Betriebsvermögen: Teileinkünfteverfahren, 60 % steuerpflichtig (§ 3 Nr. 40 EStG), Aufwendungen zu 60 % abziehbar (§ 3c Abs. 2 EStG). Kapitalgesellschaft als Anteilseignerin: Dividenden und Veräußerungsgewinne sind nach § 8b Abs. 1 und 2 KStG steuerfrei, 5 % gelten aber als nichtabziehbare Betriebsausgaben (§ 8b Abs. 3, 5 KStG); Dividenden aus Streubesitz unter 10 % sind steuerpflichtig (§ 8b Abs. 4 KStG).',
          'Verdeckte Gewinnausschüttung (§ 8 Abs. 3 S. 2 KStG): eine Vermögensminderung oder verhinderte Vermögensmehrung, die durch das Gesellschaftsverhältnis veranlasst ist, sich auf den Unterschiedsbetrag nach § 4 Abs. 1 EStG auswirkt und nicht auf einem ordentlichen Gewinnverteilungsbeschluss beruht. Veranlassung: Ein ordentlicher und gewissenhafter Geschäftsleiter hätte den Vorteil einem Fremden nicht gewährt (Fremdvergleich); bei beherrschenden Gesellschaftern zusätzlich, wenn keine im Voraus getroffene, klare, zivilrechtlich wirksame und tatsächlich durchgeführte Vereinbarung besteht. Folge: außerbilanzielle Hinzurechnung bei der Gesellschaft, beim Gesellschafter Kapitaleinkünfte (§ 20 Abs. 1 Nr. 1 S. 2 EStG) statt etwa Arbeitslohn. Verdeckte Einlage: Ein Gesellschafter wendet der Gesellschaft einen einlagefähigen Vermögensvorteil zu, der im Gesellschaftsverhältnis veranlasst ist; sie erhöht das Einkommen nicht (§ 8 Abs. 3 S. 3 KStG), beim Gesellschafter erhöhen sich die Anschaffungskosten der Beteiligung. Nutzungsvorteile (zinsloses Darlehen) sind nicht einlagefähig.'],
        schema: ['Leistung zwischen KapG und Gesellschafter?', 'vGA: Vermögensminderung/verhinderte Mehrung, Veranlassung durch Gesellschaftsverhältnis (Fremdvergleich, beherrschend: formelle Kriterien), Auswirkung auf Gewinn, kein Ausschüttungsbeschluss', 'Folge KapG: Hinzurechnung', 'Folge Gesellschafter: § 20 Abs. 1 Nr. 1 S. 2 EStG', 'Umgekehrt: verdeckte Einlage (§ 8 Abs. 3 S. 3)'],
        case: { sv: 'Alleingesellschafterin und Geschäftsführerin A der B-GmbH erhält 180.000 € Gehalt; angemessen wären 130.000 €. Der Vertrag wurde vor Beginn des Jahres schriftlich geschlossen. Die GmbH weist ein Einkommen von 70.000 € vor Korrektur aus.',
          steps: [['Liegt eine vGA vor, und in welcher Höhe?', 'Ja, soweit das Gehalt unangemessen ist: 50.000 € (Fremdvergleich; ein ordentlicher Geschäftsleiter hätte es einem Fremden nicht gezahlt).'], ['Folge bei der GmbH?', 'Hinzurechnung: Einkommen 120.000 €.'], ['Folge bei A?', '130.000 € Arbeitslohn (§ 19 EStG), 50.000 € Kapitaleinkünfte (§ 20 Abs. 1 Nr. 1 S. 2 EStG), im Privatvermögen mit 25 % Abgeltungsteuer.']],
          res: 'vGA 50.000 €: Einkommen GmbH 120.000 €, bei A 130.000 € § 19 und 50.000 € § 20.' },
        nav: [],
        cards: [['Merkmale der vGA?', 'Vermögensminderung oder verhinderte Mehrung, durch das Gesellschaftsverhältnis veranlasst, Auswirkung auf den Unterschiedsbetrag nach § 4 Abs. 1 EStG, kein Ausschüttungsbeschluss.'], ['Zusätzliche Kriterien beim beherrschenden Gesellschafter?', 'Im Voraus getroffene, klare, zivilrechtlich wirksame und tatsächlich durchgeführte Vereinbarung.'], ['§ 8b KStG für Dividenden?', 'Steuerfrei, aber 5 % nichtabziehbare Betriebsausgaben; Streubesitz unter 10 % steuerpflichtig.'], ['Verdeckte Einlage: Folgen?', 'Erhöht das Einkommen der KapG nicht (§ 8 Abs. 3 S. 3 KStG); beim Gesellschafter nachträgliche Anschaffungskosten. Nutzungsvorteile sind nicht einlagefähig.']] },

      { id: 'u8', t: 'Organschaft und Gewerbesteuer', norms: ['§§ 14 ff. KStG', '§ 2 GewStG', '§§ 7–11 GewStG', '§ 35 EStG'], link: 'u7',
        why: 'Zwei Brücken: Die Organschaft verbindet Gesellschaften im Konzern, die Gewerbesteuer verbindet Einkommen- und Körperschaftsteuer mit der Gemeinde.',
        core: ['Organschaft (§§ 14 ff. KStG): Das Einkommen einer Organgesellschaft wird dem Organträger zugerechnet. Voraussetzungen: Organgesellschaft ist eine Kapitalgesellschaft mit Geschäftsleitung im Inland und Sitz in der EU/im EWR; Organträger ist ein gewerbliches Unternehmen; finanzielle Eingliederung (Mehrheit der Stimmrechte vom Beginn des Wirtschaftsjahres an ununterbrochen); Gewinnabführungsvertrag auf mindestens fünf Jahre, der tatsächlich durchgeführt wird. Folge: Verluste und Gewinne innerhalb des Organkreises werden verrechnet; die Organgesellschaft bleibt Steuersubjekt, ihr Einkommen wird aber beim Organträger versteuert. Für die Gewinnabführung fällt keine Kapitalertragsteuer an. Gewerbesteuerlich gilt die Organgesellschaft als Betriebsstätte des Organträgers (§ 2 Abs. 2 S. 2 GewStG).',
          'Gewerbesteuer: Steuergegenstand ist jeder stehende Gewerbebetrieb im Inland (§ 2 GewStG), Kapitalgesellschaften stets kraft Rechtsform. Steuerschuldner ist der Unternehmer, bei Personengesellschaften die Gesellschaft (§ 5 GewStG). Gewerbeertrag (§ 7) = Gewinn nach EStG/KStG + Hinzurechnungen (§ 8, etwa ein Viertel der Finanzierungsanteile über 200.000 € Freibetrag) − Kürzungen (§ 9, etwa für Grundbesitz und Beteiligungen), Verlustvortrag (§ 10a), abgerundet auf volle 100 €, bei natürlichen Personen und Personengesellschaften abzüglich Freibetrag 24.500 €. Messbetrag = Gewerbeertrag · 3,5 % (Messbescheid des Finanzamts); Gewerbesteuer = Messbetrag · Hebesatz der Gemeinde (mindestens 200 %). Bei Einzelunternehmern und Mitunternehmern ermäßigt sich die Einkommensteuer um das 4-Fache des Messbetrags, höchstens um die tatsächlich gezahlte Gewerbesteuer (§ 35 EStG). Die Gewerbesteuer ist keine Betriebsausgabe (§ 4 Abs. 5b EStG).'],
        schema: ['Organschaft: OG (KapG), OT (gewerblich), finanzielle Eingliederung, GAV 5 Jahre durchgeführt', 'Folge: Zurechnung beim OT, keine KapESt, GewSt-Betriebsstätte', 'GewSt: Gewinn + § 8 − § 9 = Gewerbeertrag', 'Abrunden, Freibetrag 24.500 € (nur EU/PersG)', '· 3,5 % = Messbetrag · Hebesatz', '§ 35 EStG: 4-facher Messbetrag, max. tatsächliche GewSt'],
        case: { sv: 'Einzelunternehmer U hat einen Gewinn von 80.000 €. Hinzurechnungen und Kürzungen gibt es nicht. Der Hebesatz seiner Gemeinde beträgt 400 %.',
          steps: [['Gewerbeertrag nach Freibetrag?', '80.000 − 24.500 = 55.500 €.'], ['Messbetrag und Gewerbesteuer?', '55.500 · 3,5 % = 1.942,50 €; · 400 % = 7.770 €.'], ['Anrechnung nach § 35 EStG?', '4 · 1.942,50 = 7.770 €, höchstens die gezahlte GewSt 7.770 €: Die ESt sinkt um 7.770 €; bei einem Hebesatz von 400 % wird die GewSt rechnerisch voll ausgeglichen.']],
          res: 'GewSt 7.770 €, § 35-Ermäßigung 7.770 €.' },
        nav: [],
        cards: [['Voraussetzungen der körperschaftsteuerlichen Organschaft?', 'OG: KapG mit Geschäftsleitung im Inland; OT: gewerbliches Unternehmen; finanzielle Eingliederung ab Beginn des WJ; GAV mindestens fünf Jahre, tatsächlich durchgeführt.'], ['Rechtsfolge der Organschaft?', 'Das Einkommen der Organgesellschaft wird dem Organträger zugerechnet; bei der GewSt gilt die OG als Betriebsstätte.'], ['Gewerbesteuer-Rechenweg?', 'Gewinn + Hinzurechnungen − Kürzungen, abrunden, ggf. − 24.500 €, · 3,5 % Messzahl, · Hebesatz.'], ['§ 35 EStG?', 'ESt-Ermäßigung um das 4-Fache des GewSt-Messbetrags, höchstens um die tatsächlich zu zahlende GewSt.']] },
    ],
  },
  BOSS: {
    grund: { t: 'Fall Seestadt-Satzung', sv: 'Die Gemeinde Seestadt beschließt im Mai eine Satzung über eine Steuer auf Bootsliegeplätze rückwirkend zum 1. Januar, um den Haushalt zu sanieren und zugleich Dauerlieger zu verdrängen. Eigner E klagt.',
      steps: [['Ist die Abgabe eine Steuer?', 'Ja: Geldleistung ohne Gegenleistung zur Einnahmeerzielung (Lenkung als Nebenzweck genügt, § 3 Abs. 1 AO).', 'g2'], ['Wer hat die Gesetzgebungskompetenz?', 'Örtliche Aufwandsteuer: Länder (Art. 105 Abs. 2a GG), Satzungsrecht der Gemeinde nach Landesrecht.', 'g5'], ['Rückwirkung zum 1. Januar: echt oder unecht?', 'Für einen jährlich entstehenden Steueranspruch des laufenden Jahres unechte Rückwirkung; grundsätzlich zulässig, Vertrauensschutz abwägen.', 'g4'], ['Wie beginnt die Antwort im Gutachten?', 'Mit der Fallfrage: Die Klage hat Aussicht auf Erfolg, wenn sie zulässig und begründet ist.', 'g1'], ['Darf die Steuer erdrosselnd hoch sein?', 'Nein: Eine Lenkungsteuer darf nicht erdrosseln und muss gleichheitsgerecht sein.', 'g5']],
      res: 'Steuer, Landeskompetenz über Satzung, unechte Rückwirkung, Gutachtenaufbau Klage, Erdrosselungsverbot.' },
    ao: { t: 'Fall Hafenlogistik GmbH', sv: 'Geschäftsführer H der insolventen Hafenlogistik GmbH soll für nicht abgeführte Lohnsteuer haften. Der Haftungsbescheid wird am Dienstag zur Post gegeben, H legt sechs Wochen später Einspruch ein. Parallel will das Finanzamt seinen ESt-Bescheid 2020 ändern, weil es von einer nicht erklärten Abfindung erfährt.',
      steps: [['Ermächtigung für den Haftungsbescheid?', '§ 191 Abs. 1 AO i. V. m. § 69, § 34 AO.', 'a2'], ['Haftet H für die Lohnsteuer anteilig oder voll?', 'Voll: Bei der Lohnsteuer gilt der Grundsatz der anteiligen Tilgung nicht.', 'a2'], ['Ist der Einspruch nach sechs Wochen fristgerecht?', 'Nein, die Frist beträgt einen Monat ab Bekanntgabe (Fiktion am vierten Tag); möglich ist nur Wiedereinsetzung bei unverschuldeter Versäumnis.', 'a8'], ['Welche Norm erlaubt die Änderung wegen der Abfindung?', '§ 173 Abs. 1 Nr. 1 AO: neue Tatsache, nachträglich bekannt, höhere Steuer.', 'a7'], ['Was ist vorher zu prüfen?', 'Ob die Festsetzungsfrist (vier Jahre ab Ablauf des Abgabejahres, max. drei Jahre Anlaufhemmung) noch läuft.', 'a5']],
      res: 'Haftung nach § 69/§ 191 AO voll, Einspruch verfristet, Änderung nach § 173 Abs. 1 Nr. 1 AO bei offener Festsetzungsfrist.' },
    est: { t: 'Fall Familie Brandt', sv: 'Ines Brandt wohnt in Kassel, ist angestellte Ingenieurin mit Dienstwagen, vermietet die Einliegerwohnung an ihre Nichte zu 40 % der Marktmiete, verkauft nach acht Monaten Bitcoin mit Gewinn und lässt nach einem Unfall ihr Bad umbauen.',
      steps: [['Steuerpflicht?', 'Unbeschränkt: Wohnsitz im Inland (§ 1 Abs. 1 EStG, § 8 AO).', 'e1'], ['Wie wird der Dienstwagen erfasst?', '1 %-Regel plus 0,03 % je Entfernungskilometer, Benzin abgegolten (§ 8 Abs. 2 EStG).', 'e4'], ['Einliegerwohnung zu 40 %?', 'Aufteilung, Werbungskosten nur zu 40 % abziehbar (§ 21 Abs. 2 EStG).', 'e7'], ['Bitcoin-Gewinn nach acht Monaten?', 'Privates Veräußerungsgeschäft (§ 23 Abs. 1 S. 1 Nr. 2 EStG, Haltedauer unter einem Jahr), Freigrenze 1.000 €.', 'e8'], ['Badumbau?', 'Außergewöhnliche Belastung, soweit über der zumutbaren Belastung (§ 33 EStG).', 'e9']],
      res: 'Unbeschränkt steuerpflichtig, 1 %-Regel, Aufteilung bei VuV, § 23 für Bitcoin, agB für den Umbau.' },
    unt: { t: 'Fall Lindner KG und Lindner GmbH', sv: 'Ludwig Lindner (60) ist Kommanditist der Lindner KG, die ihm Gehalt und Miete für ein Lager zahlt. Er verkauft seinen KG-Anteil mit hohem Gewinn. Seine Tochter ist Alleingesellschafterin der Lindner GmbH, die ihr ein überhöhtes Gehalt zahlt und die die KG später als Organträgerin übernehmen soll.',
      steps: [['Gehalt und Miete der KG an Ludwig?', 'Sondervergütungen, gewerbliche Einkünfte (§ 15 Abs. 1 S. 1 Nr. 2 EStG); das Lager ist SBV I.', 'u3'], ['Verkauf des KG-Anteils?', 'Veräußerung eines Mitunternehmeranteils (§ 16 Abs. 1 Nr. 2 EStG), Freibetrag ab 55 mit Abschmelzung über 136.000 €.', 'u5'], ['Das überhöhte Gehalt der Tochter?', 'Soweit unangemessen vGA (§ 8 Abs. 3 S. 2 KStG), bei ihr Kapitaleinkünfte.', 'u7'], ['Kann die KG Organträgerin der GmbH werden?', 'Ja, als gewerbliches Unternehmen, bei finanzieller Eingliederung und fünfjährigem, durchgeführtem GAV.', 'u8'], ['Wer ist bei der KG Steuerschuldner der Gewerbesteuer?', 'Die KG selbst (§ 5 Abs. 1 S. 3 GewStG).', 'u8']],
      res: 'Sondervergütungen, § 16 für den Anteil, vGA beim Gehalt, Organschaft möglich, KG schuldet GewSt.' },
  },
  LINKS: {
    g2: ['g1', 'Warum ist der Steuerbegriff für die Fallbearbeitung wichtig?', 'Er entscheidet, ob AO und Finanzrechtsweg gelten; erst dann stellen sich Fragen nach Bescheid, Einspruch und Klage.'],
    g3: ['g2', 'Was folgt aus dem Charakter der Steuer als Eingriff?', 'Ohne gesetzlichen Tatbestand keine Steuer; daher Analogieverbot zulasten des Bürgers und die Bedeutung der Auslegung.'],
    g4: ['g3', 'Wie hängen Gesetzesvorbehalt und Rückwirkungsverbot zusammen?', 'Beide schützen das Vertrauen in die Geltung des Gesetzes: Der Bürger muss vorher wissen können, was steuerpflichtig ist.'],
    g5: ['g4', 'Wo stehen Kompetenzfragen im Prüfschema?', 'Eine Steuer ohne Gesetzgebungskompetenz ist verfassungswidrig; das wird inzident bei der Ermächtigungsgrundlage relevant.'],
    a1: ['g2', 'Warum ist der Steuerbescheid nicht konstitutiv?', 'Weil die Steuer als gesetzliche Leistungspflicht schon mit der Tatbestandsverwirklichung entsteht; der Bescheid stellt sie nur verbindlich fest.'],
    a2: ['a1', 'Was heißt Akzessorietät der Haftung?', 'Ohne bestehende Steuerschuld kein Haftungsanspruch; erlischt die Steuerschuld, entfällt grundsätzlich auch die Haftung.'],
    a3: ['a1', 'Wozu braucht es die Bekanntgabe, wenn die Steuer schon entstanden ist?', 'Erst mit Bekanntgabe wird die Festsetzung wirksam, beginnt die Einspruchsfrist und wird die Steuer meist fällig.'],
    a4: ['a3', 'Wie hängen Mitwirkungspflicht und Änderung nach § 173 AO zusammen?', 'Wer seine Mitwirkungspflichten verletzt, kann sich nicht auf Ermittlungsfehler des Finanzamts berufen; die Änderung bleibt möglich.'],
    a5: ['a4', 'Warum verlängern Hinterziehung und Leichtfertigkeit die Festsetzungsfrist?', 'Weil das Finanzamt die Verkürzung in der Regel erst spät entdeckt; der Steuerpflichtige soll sich nicht auf die Verjährung verlassen können.'],
    a6: ['a5', 'Warum braucht es § 171 Abs. 10 AO?', 'Sonst könnte der Folgebescheid verjähren, bevor der Grundlagenbescheid ergeht, und die Bindung liefe ins Leere.'],
    a7: ['a6', 'Warum werden §§ 164, 165 AO zuerst geprüft?', 'Weil § 172 Abs. 1 AO nur für Bescheide gilt, die nicht unter Vorbehalt oder vorläufig ergangen sind.'],
    a8: ['a7', 'Was ist der Unterschied zwischen Einspruch und Änderungsantrag?', 'Der Einspruch eröffnet die volle Überprüfung (auch Verböserung); der Antrag nach § 172 Abs. 1 Nr. 2a AO wirkt nur im beantragten Umfang.'],
    e1: ['g1', 'Wo steht die Steuerpflicht im materiellen Prüfschema?', 'Ganz vorn: Ohne persönliche Steuerpflicht gibt es keine Einkünfte zu prüfen.'],
    e2: ['e1', 'Warum spielt die Einkunftsart für die Höhe eine Rolle?', 'Wegen des Dualismus: Gewinneinkünfte erfassen auch Wertsteigerungen der Quelle, Überschusseinkünfte grundsätzlich nicht.'],
    e3: ['e2', 'Warum gibt es § 12 Nr. 1 EStG?', 'Es setzt das Veranlassungsprinzip um: Lebensführung ist Einkommensverwendung, nicht Einkommenserzielung.'],
    e4: ['e3', 'Was ist an der 1 %-Regel ein Sachbezug?', 'Die Nutzungsmöglichkeit ist eine Einnahme in Geldeswert (§ 8 Abs. 1, Abs. 2 EStG); die 1 %-Regel bewertet sie pauschal.'],
    e5: ['e2', 'Wie hängen Liebhaberei und Gewerbebetrieb zusammen?', 'Gewinnerzielungsabsicht ist Merkmal des Gewerbebetriebs; fehlt sie, liegt kein Gewerbe, sondern Liebhaberei vor.'],
    e6: ['e5', 'Warum ist die Gewinnermittlungsart wichtig?', 'Sie entscheidet über den Zeitpunkt der Erfassung: Realisation (Bilanz) oder Zufluss (EÜR).'],
    e7: ['e3', 'Was unterscheidet § 20 von den übrigen Überschusseinkünften?', 'Gesonderter Tarif von 25 % und kein Abzug tatsächlicher Werbungskosten, nur der Sparer-Pauschbetrag.'],
    e8: ['e7', 'Warum geht § 17 dem § 20 Abs. 2 EStG vor?', 'Wegen der wesentlichen Beteiligung ab 1 % ordnet das Gesetz die Gewinne den gewerblichen Einkünften zu (Teileinkünfteverfahren statt Abgeltungsteuer).'],
    e9: ['e2', 'Wo stehen Sonderausgaben und agB im Schema?', 'Zwischen GdE und Einkommen: Sie verwirklichen das subjektive Nettoprinzip.'],
    u1: ['e5', 'Wann ist ein Einzelunternehmer gewerblich?', 'Wenn seine Betätigung die Merkmale des § 15 Abs. 2 EStG erfüllt; dann gilt § 15 Abs. 1 Nr. 1 EStG.'],
    u2: ['u1', 'Was unterscheidet den Mitunternehmer vom Einzelunternehmer?', 'Er betreibt den Betrieb gemeinsam mit anderen; die Gesellschaft ermittelt den Gewinn, der ihm anteilig zugerechnet wird.'],
    u3: ['u2', 'Warum werden Sondervergütungen umqualifiziert?', 'Damit der Mitunternehmer dem Einzelunternehmer gleichsteht, der sich selbst kein Gehalt zahlen kann.'],
    u4: ['u3', 'Was hat die Abfärbung mit dem Feststellungsverfahren zu tun?', 'Ob die Einkünfte gewerblich sind, wird im Feststellungsbescheid der Gesellschaft entschieden und bindet die Gesellschafter.'],
    u5: ['u3', 'Was gehört bei der Veräußerung eines Mitunternehmeranteils dazu?', 'Auch das Sonderbetriebsvermögen, soweit es wesentliche Betriebsgrundlage ist; sonst liegt keine begünstigte Veräußerung vor.'],
    u6: ['u1', 'Was folgt aus dem Trennungsprinzip für die GmbH?', 'Sie ist eigenes Steuersubjekt der KSt; ihr Einkommen wird nicht den Gesellschaftern zugerechnet.'],
    u7: ['u6', 'Warum korrigiert man die vGA außerhalb der Bilanz?', 'Weil sie handelsrechtlich Aufwand ist, steuerlich aber Einkommensverwendung; die Korrektur erfolgt bei der Einkommensermittlung.'],
    u8: ['u7', 'Wie wird die Doppelbelastung mit Gewerbesteuer abgemildert?', 'Bei Personenunternehmen durch § 35 EStG; bei Kapitalgesellschaften gar nicht, sie zahlen KSt und GewSt nebeneinander.'],
  },
};
